module fsm(input IN, input CLK, input RST, output reg MATCH) ;
    reg [3:0] state = 4'b0000;
    reg [3:0] in_cont = 4'b0000;
    always @(IN or posedge CLK or posedge RST)
    begin
        if (RST)
        begin
            MATCH <= 0;
        end
        else
        begin
            in_cont[3] = in_cont[2];
            in_cont[2] = in_cont[1];
            in_cont[1] = in_cont[0];
            in_cont[0] = IN;
            case (state)
                4'b0000: begin
                    state <= IN ? 4'b0001 : 4'b0000;
                    MATCH <= 0;
                end
                4'b0001: begin
                    state <= IN ? 4'b0001 : 4'b0010;
                    MATCH <= 0;
                end
                4'b0010: begin
                    state <= IN ? 4'b0011 : 4'b0000;
                    MATCH <= 0;
                end
                4'b0011: begin
                    state <= IN ? 4'b0011 : 4'b0100;
                    MATCH <= 0;
                end
                4'b0100: begin
                    state <= IN ? 4'b1101 : 4'b0000;
                    MATCH <= 0;
                end
                4'b0101: begin
                    state <= 4'b0110;
                    MATCH <= 0;
                end
                4'b0110: begin
                    state <= IN ? 4'b0110 : 4'b0111;
                    MATCH <= 0;
                end
                4'b0111: begin
                    state <= IN ? 4'b1000 : 4'b0000;
                    MATCH <= 0;
                end
                4'b1000: begin
                    state <= IN ? 4'b1000 : 4'b1001;
                    MATCH <= 0;
                end
                4'b1001: begin
                    state <= IN ? 4'b0001 : 4'b0010;
                    MATCH <= (in_cont == 4'b10011);
                end
                4'b1101: begin
                    state <= IN ? 4'b1101 : 4'b0101;
                    MATCH <= 0;
                end
                4'b1111: begin
                    state <= IN ? 4'b1110 : 4'b0000;
                    MATCH <= 0;
                end
                default: begin
                    state <= 4'b0000;
                    MATCH <= 0;
                end
            endcase
        end
    end
endmodule

