module sequence_detector(clk, reset_n, data_in, sequence_detected) ;
    input clk, reset_n, data_in;
    output reg sequence_detected;

    parameter IDLE = 4'b0000, S1 = 4'b0001, S2 = 4'b0010, S3 = 4'b0011, S4 = 4'b0100;
    reg [3:0] current_state, next_state;
    always @(posedge clk or negedge reset_n) begin
        if (~reset_n) begin
            current_state <= IDLE;
        end else begin
            current_state <= next_state;
        end
    end
    always @(*) begin

        next_state = current_state;
        sequence_detected = 1'b0;
        case (current_state)
            IDLE: begin
                if (data_in) begin
                    next_state = S1;
                end
            end
            S1: begin
                if (~data_in) begin
                    next_state = S2;
                end
            end
            S2: begin
                if (data_in) begin
                    next_state = S3;
                end
            end
            S3: begin
                if (data_in) begin
                    next_state = S4;
                end else begin
                    next_state = S1;
                end
            end
            S4: begin
                if (data_in) begin
                    sequence_detected = 1'b1;
                end else begin
                    next_state = S2;
                end
            end
        endcase
    end
endmodule

