module LIFObuffer(
                  dataIn,
                  RW,
                  EN,
                  Rst,
                  Clk,
                  EMPTY,
                  FULL,
                  dataOut
                  ) ;
   input   [3:0] dataIn;

   input         RW;

   input         EN;

   input         Rst;
   input         Clk;
   output        EMPTY;
   output        FULL;
   output  [3:0] dataOut;

   reg    [3:0] stack_mem [3:0];

   reg    [2:0] SP;

   reg    [3:0] dataOut;



   integer i;
   always @(posedge Clk)
     begin : STACK
        if (Rst) begin
           for (i = 0;
 i < 4;
 i = i + 1)
             stack_mem[i] <= 0;
           SP          <= 4;

        end
        else if (EN) begin
           if (RW == 1'b1 && SP < 4) begin 
              dataOut   <= stack_mem[SP];
              stack_mem[SP] <= 0;
              SP <= SP + 1;
           end
           else if (RW == 1'b0 && SP > 0) begin 
              SP <= SP - 1;
              stack_mem[SP] <= dataIn;
           end
        end
     end
   assign EMPTY = (SP == 3'b100) ? 1'b1 : 1'b0;
   assign FULL  = (SP == 3'b000) ? 1'b1 : 1'b0;
endmodule

