module parallel2serial(
	clk,
	rst_n,
	d,
	valid_out,
	dout
) ;
input                clk              ;
input                rst_n            ;
input      [3 : 0]   d                ;
output               valid_out        ;
output               dout             ;
reg        [4 : 0]   cnt              ;
reg        [3 : 0]   data             ;
reg                  valid            ;
always @ (posedge clk or negedge rst_n) begin
	if (rst_n == 1'b0) begin
		data <= 4'd0 ;
		cnt  <= 5'd0 ;
		valid <= 1'b0;
	end
	else begin
		if(cnt == 3) begin
			data <= d;
			cnt  <= 5'd0;
			valid <= 1'b1;
		end
		else begin
			cnt  <= cnt + 1'b1 ;
			valid <= 1'b0      ;
			data  <= {data[2:0],1'b0} ;
		end
	end
end
assign valid_out = valid;
assign dout      = data[3];
endmodule

