module pulse_detect(clk, rst_n, data_in, data_out) ;
    input clk, rst_n, data_in ;
    output data_out ;
    reg [2:0] state ;
    reg data_out ;
    always @(posedge clk, negedge rst_n)
    begin
        if(~rst_n)
        begin
            state <= 3'd0 ;
            data_out <= 1'b0 ;
        end
        else
        begin
            case(state)
                3'd0 : state <= data_in ? 3'd1 : 3'd0 ;
                3'd1 : state <= data_in ? 3'd2 : 3'd0 ;
                3'd2 : state <= data_in ? 3'd3 : 3'd0 ;
                3'd3 : state <= data_in ? 3'd4 : 3'd0 ;
                3'd4 : state <= data_in ? 3'd4 : 3'd0 ;
                default : state <= data_in ? 3'd1 : 3'd0 ;
            endcase
            if(state == 3'd4)
                data_out <= 1'b1 ;
            else
                data_out <= 1'b0 ;
        end
    end
endmodule

