module traffic_light(
	input rst_n, 
	input clk, 
	input pass_request,
	output [7:0] clock, 
	output red, 
	output yellow, 
	output green
);

reg [7:0] cnt;
reg [1:0] state, next_state;

localparam idle = 2'b00;
localparam s1_red = 2'b01;
localparam s2_yellow = 2'b10;
localparam s3_green = 2'b11;
reg p_red, p_yellow, p_green;
always@(posedge clk, negedge rst_n) begin
	if(!rst_n) state <= idle;
	else state <= next_state;
end

always@(state, cnt) begin
	case (state)
		idle: if(cnt == 0) next_state = s1_red;
			else next_state = idle;
		s1_red: if(cnt == 0) next_state = s3_green;
			else next_state = s1_red;
		s2_yellow: if(cnt == 0) next_state = s1_red;
			else next_state = s2_yellow;
		s3_green: if(cnt == 0) next_state = s2_yellow;
			else next_state = s3_green;
	endcase
end

always@(posedge clk, negedge rst_n) begin
	if(!rst_n) cnt <= 10;
	else if (pass_request && green) cnt <= 10;
	else if (!green && p_green) cnt <= 60;
	else if (!yellow && p_yellow) cnt <= 5;
	else if (!red && p_red) cnt <= 10;
	else cnt <= cnt - 1'b1;
end

assign clock = cnt;
always@(posedge clk, negedge rst_n) begin
	if(!rst_n) begin 
		{p_red, p_yellow, p_green} <= 3'b000;
	end
	else begin
		{p_red, p_yellow, p_green} <= {red, yellow, green};
	end
end
assign red = (state == s1_red)? 1'b1: 1'b0;
assign yellow = (state == s2_yellow)? 1'b1: 1'b0;
assign green = (state == s3_green)? 1'b1: 1'b0;
endmodule

