module edge_detect(clk, rst_n, a, rise, down) ;
    input clk ;

    input rst_n ;

    input a ;

    output reg rise ;

    output reg down ;

    reg a_pre ;

    always @(posedge clk) begin
        if (~rst_n) begin

            a_pre <= a ;
            rise <= 0 ;
            down <= 0 ;
        end else begin

            a_pre <= a ;

            if ((a == 1) && (a_pre == 0)) begin
                rise <= 1 ;

                down <= 0 ;

            end

            else if ((a == 0) && (a_pre == 1)) begin
                rise <= 0 ;

                down <= 1 ;

            end else begin

                rise <= 0 ;
                down <= 0 ;
            end
        end
    end
endmodule

