	if ( !rst_n ) begin
		valid_out_reg <= 0 ;
		data_out_reg <= 0 ;
	end 
	else begin
		if ( valid_in & flag ) begin 
			data_out_reg <= {data_lock , data_in} ;
			valid_out_reg <= 1 ;
		end
		else valid_out_reg <= 0 ;
	end
