module serial2parallel(
	clk,
	rst_n,
	din_serial,
	din_valid,
	dout_parallel,
	dout_valid
	) ;
	input			clk, rst_n;
	input			din_serial, din_valid;
	output	[7:0]	dout_parallel;
	output			dout_valid;

	reg [3:0] cnt;
	reg [7:0] din_serial_tmp;
	always @(posedge clk or negedge rst_n)
	begin
	    if (rst_n == 1'b0) begin
	        cnt <= 4'd0;
	    end else begin
	        if(din_valid == 1'b1) begin
	            cnt <= cnt + 1'b1;
	        end
	        if(cnt == 4'd8) begin
	            cnt <= 4'd0;
	        end
	    end
	end
	reg [7:0] dout_parallel_tmp;
	always @(posedge clk or negedge rst_n)
	begin
	    if (rst_n == 1'b0) begin
	        dout_parallel_tmp <= 8'd0;
	    end else begin
	        if(cnt != 4'd0 && din_valid == 1'b1) begin
	            dout_parallel_tmp <= dout_parallel_tmp >> 1;
	            dout_parallel_tmp[7] <= din_serial;
	        end
	    end
	end
	reg dout_valid_tmp;
	always @(posedge clk or negedge rst_n)
	begin
	    if (rst_n == 1'b0) begin
	        dout_valid_tmp <= 1'b0;
	    end else begin
	        if(cnt == 4'd8) begin
	            dout_valid_tmp <= 1'b1;
	        end else begin
	            dout_valid_tmp <= 1'b0;
	        end
	    end
	end
	assign dout_parallel = dout_parallel_tmp;
	assign dout_valid = dout_valid_tmp;
endmodule

