module alu(a, b, aluc, r, zero, carry, negative, overflow, flag) ;
    input [31:0] a ;
    input [31:0] b ;
    input [5:0] aluc ;
    output reg[31:0] r ;
    output zero, carry, negative, overflow, flag ;
    wire [31:0] add, addu, sub, subu, and_, or_, xor_, nor_, slt, sltu, sll, srl, sra, sllv, srlv, srav ;
    wire [4:0] shamt ;
    wire [31:0] slvi, srvi, sravi, sravi, srlu, srru, srau, srruu ;
    assign shamt = a[4:0] ;

    assign zero = (r == 32'd0) ? 1'b1 : 1'b0 ;
    assign negative = r[31] ;
    assign overflow = ({ad, subd} == 2'b01) ? 1'b1 : 1'b0 ;
    assign carry = ({ad, subd} == 2'b01) ? 1'b1 : 1'b0 ;

    assign {cout, add} = a + b ;
    assign {coutu, addu} = a + b ;

    assign {_, sub} = a - b ;
    assign {_, subu} = a - b ;
    assign {ad, subd} = {add[31], sub[31]} ;

    assign and_ = a & b ;

    assign or_ = a | b ;

