   reg           start_cnt;
   reg           finish_cnt;
   assign dividend_sign = dividend[7];
   assign divisor_sign = divisor[7];
   assign sign_out = dividend_sign ^ divisor_sign;
   always @ (*) begin
      start_cnt = finish_cnt;
      if(opn_valid) begin
         start_cnt = 1'b1;
         dividend_T1 = {1'b0, dividend};
         divisor_T1 = {1'b0, divisor};
         DIVISOR_T1 = divisor_T1;
         NEG_DIVISOR = ~DIVISOR_T1 + 1'b1;
         if(sign) begin
            if(divisor == 8'h00) begin
               start_cnt = 1'b0;
            end
         end
      end
   end
   always @ (*) begin
      cnt_next = cnt + 1'b1;
      if(cnt == 4'h8) begin
         cnt_next = 4'h0;
      end
      finish_cnt = cnt_next == 4'h8;
   end
   always @ (*) begin
      if (sign_out) begin
         dividend_abs_T1 = -dividend_T1;
         div_abs_T1 = -DIVISOR_T1;
      end else begin
         dividend_abs_T1 = dividend_T1;
         div_abs_T1 = DIVISOR_T1;
      end
