         cnt <= 4'h0;
         sr <= 16'h0000;
      end else begin
         if(res_valid) begin
            sr <= 16'h0000;
            cnt <= 4'h0;
         end else begin
            sr <= SR_T1;
            cnt <= cnt_next;
         end
      end
   end
   always @ (posedge clk) begin
      sign_T1 <= sign;
   end
   always @ (*) begin
      res_valid_T1 = 1'b0;
      if(rst) begin
         res_valid_T1 = 1'b0;
      end else begin
