input  [3:0] A ;
input  [3:0] B ;

output reg A_greater ;
output reg A_equal ;
output reg A_less ;
reg [3:0] A_sub_B ;
reg A_less_temp ;
reg A_greater_temp ;
reg A_equal_temp ;
    always @(A, B)
    begin
        A_less_temp = 0 ;
        A_greater_temp = 0 ;
        A_equal_temp = 0 ;
        A_sub_B = A-B ;

        if (A_sub_B[3]) begin 
           A_less_temp = 1 ;
           A_greater_temp = 0 ;
           A_equal_temp = 0 ;
        end
        else if (A_sub_B)  begin
           A_less_temp = 0 ;
           A_greater_temp = 1 ;
           A_equal_temp = 0 ;
        end
        else if (A_sub_B == 0) begin
           A_less_temp = 0 ;
           A_greater_temp = 0 ;
           A_equal_temp = 1 ;
        end
    A_less = A_less_temp ;
    A_greater = A_greater_temp ;
    A_equal = A_equal_temp ;

    end 
