module adder_bcd(A, B, Cin, Sum, Cout) ;
    input [3:0] A, B ;
    input Cin ;
    output [3:0] Sum ;
    output Cout ;
    wire [4:0] sum_tmp ;

    wire [3:0] correction ;
    wire [3:0] b_tmp ;

    wire correction_carry ;

    assign sum_tmp = A + B + Cin ;


    assign correction = (sum_tmp[3:0] > 4'd9) ? 4'd6 : 4'd0 ;

    assign b_tmp = (sum_tmp[3:0] > 4'd9) ? sum_tmp[3:0] - 4'd9 : sum_tmp[3:0] ;

    assign Cout = (sum_tmp[3:0] > 4'd9) ? 1'b1 : 1'b0 ;

    assign Sum = correction + b_tmp ;
endmodule

