module sub_64bit ( 
    input [63:0] A ,
    input [63:0] B ,
    output [63:0] result ,
    output overflow 
) ;
reg [63:0] rResult ;
reg rOverflow ;
assign result = rResult ;
assign overflow = rOverflow ;
always @ (*) begin
    rResult = A - B ;
    rOverflow = 0 ;

    if (A[63] == 1'b0 && B[63] == 1'b1 && rResult[63] == 1'b1) begin
        rOverflow = 1'b1 ;
    end else if (A[63] == 1'b1 && B[63] == 1'b0 && rResult[63] == 1'b0) begin
        rOverflow = 1'b1 ;
    end else begin
        rOverflow = 1'b0 ;
    end
end
endmodule

