module sequence_detector(clk, reset_n, data_in, sequence_detected) ;
    input clk;
    input reset_n;
    input data_in;
    output reg sequence_detected;

    reg [1:0] current_state;
    reg [1:0] next_state;

    parameter IDLE = 2'b00;
    parameter S1 = 2'b01;
    parameter S2 = 2'b10;
    parameter S3 = 2'b11;
    parameter S4 = 2'b100;

    always @(posedge clk) begin
        if (reset_n == 1'b0) begin
            current_state <= IDLE;
        end else begin
            current_state <= next_state;
        end
    end

    always @(*) begin
        next_state = current_state;
        sequence_detected = 1'b0;
        case (current_state)
            IDLE: begin
                if (data_in == 1) begin
                    next_state = S1;
                end
            end
            S1: begin
                if (data_in == 0) begin
                    next_state = S2;
                end
            end
            S2: begin
                if (data_in == 0) begin
                    next_state = S3;
                end
            end
            S3: begin
                if (data_in == 1) begin
                    next_state = S4;
                end
            end
            S4: begin
                sequence_detected = 1'b1;
                next_state = IDLE;
            end
            default: begin
                next_state = IDLE;
            end
        endcase
    end
endmodule

