module LIFObuffer(dataIn,RW,EN,Rst,Clk,EMPTY,FULL,dataOut) ;
	input [3:0] dataIn ;
	input RW,EN,Rst,Clk ;
	output EMPTY,FULL ;
	output [3:0] dataOut ;
	reg [3:0] stack_mem [0:3] ;
	reg [2:0] SP ;

	wire EMPTY ;
	wire FULL ;
	wire [3:0] dataOut ;
	assign EMPTY = !SP ;
	assign FULL = !(SP ^ 3'b100) ;
	assign dataOut = stack_mem[SP] ;
	always @(posedge Clk) begin
		if (EN) begin
			if (Rst) begin
				{stack_mem[0], stack_mem[1],stack_mem[2],stack_mem[3]} <= 12'h0 ;
				SP <= 3'b100 ;
			end
			else begin
				if (RW) begin 
					if(!EMPTY) begin
						stack_mem[SP] <= 0 ;
						SP <= SP + 3'b001 ;
					end
				end
				else begin 
					if (!FULL) begin
						stack_mem[SP-3'b001] <= dataIn ;
						SP <= SP - 3'b001 ;
					end
				end
			end
		end
	end
endmodule

