module pulse_detect(clk, rst_n, data_in, data_out) ;
    input clk, rst_n, data_in;
    output data_out ;
    reg data_out ;
    reg [2:0] state ;
    always @ (posedge clk or negedge rst_n)
    begin 
        if(~rst_n) 
        begin 
            state <= 3'b000;
            data_out <= 0 ;
        end 
        else begin 
            case(state)
                3'b000: begin 
                    if(data_in==1)
                        state <= 3'b001;
                    else 
                        state <= 3'b000;
                    data_out <= 0;
                end 
                3'b001: begin
                    if(data_in==1)
                        state <= 3'b010;
                    else 
                        state <= 3'b001;
                    data_out <= 0;
                end
                3'b010: begin
                    if(data_in==1)
                        state <= 3'b011;
                    else 
                        state <= 3'b000;
                    data_out <= 0;
                end
                3'b011: begin
                    if(data_in==0)
                        state <= 3'b100;
                    else 
                        state <= 3'b001;
                    data_out <= 0;
                end
                3'b100: begin
                    if(data_in==0)
                        state <= 3'b101;
                    else 
                        state <= 3'b000;
                    data_out <= 0;
                end
                3'b101: begin
                    if(data_in==1)
                        state <= 3'b110;
                    else 
                        state <= 3'b000;
                    data_out <= 0;
                end
                3'b110: begin
                    if(data_in==0)
                        state <= 3'b111;
                    else 
                        state <= 3'b000;
                    data_out <= 0;
                end
                3'b111: begin
                    if(data_in==1) begin
                        data_out <= 1;
                        state <= 3'b110;
                    end
                    else
                        state <= 3'b000;
                end
            endcase
        end
    end
endmodule

