    input [31:0] a, b;
    output reg [31:0] z;
    reg [2:0] counter;
    reg [23:0] a_mantissa, b_mantissa, z_mantissa;
    reg [9:0] a_exponent, b_exponent, z_exponent;
    reg a_sign, b_sign, z_sign;
    reg [49:0] product;
    reg guard_bit, round_bit, sticky;
    always @(posedge clk or posedge rst)
    begin
        if (rst)
        begin
            counter <= 3'b000;
        end
        else
        begin
            counter <= counter + 1;
        end
    end
    always @(posedge clk)
    begin
        case (counter)
            3'b001:
            begin
                a_mantissa <= {{8{1'b0}}, a[22:0]};
                b_mantissa <= {{8{1'b0}}, b[22:0]};
                a_exponent <= a[30:23];
                b_exponent <= b[30:23];
                a_sign <= a[31];
                b_sign <= b[31];
            end
            3'b010:
            begin
                z_sign <= a_sign ^ b_sign;
                if (a_exponent == 8'hff && a_mantissa == 24'h0)
                begin
                    z_mantissa <= b_mantissa;
                    z_exponent <= b_exponent;
                end
                else if (b_exponent == 8'hff && b_mantissa == 24'h0)
                begin
                    z_mantissa <= a_mantissa;
                    z_exponent <= a_exponent;
                end
                else
                begin
                    z_mantissa <= a_mantissa;
                    z_exponent <= a_exponent;
                end
            end
            3'b011:
            begin
                if (z_mantissa[23] == 1'b1)
                begin
                    z_mantissa <= z_mantissa >> 1;
                    z_exponent <= z_exponent + 1;
                end
            end
            3'b100:
            begin
                product <= a_mantissa * b_mantissa;
                guard_bit <= product[24];
                round_bit <= product[23];
                sticky <= |product[22:0];
            end
            3'b101:
            begin
                if (guard_bit)
                begin
                    z_mantissa <= round_bit ? z_mantissa + 1 : z_mantissa;
                    z_exponent <= z_exponent + 1;
                end
                else
                begin
                    z_mantissa <= z_mantissa[22:0];
                end
            end
            3'b110:
            begin
                if (z_mantissa == 24'h800000)
                begin
                    z_mantissa <= z_mantissa[22:0];
                    z_exponent <= z_exponent - 1;
                end
            end
            3'b111:
            begin
                if (z_exponent == 8'hff)
                begin
                    z_mantissa <= 24'h0;
                end
            end
        endcase
    end
    always @(posedge clk)
    begin
        case (counter)
            3'b001:
                z[22:0] <= z_mantissa[22:0];
            3'b010, 3'b011, 3'b100, 3'b101:
                z[22:0] <= z_mantissa[22:0];
            3'b110:
                z[30:23] <= z_exponent + 8'd127;
            3'b111:
                z[30:23] <= z_exponent + 8'd127;
        endcase
    end
    always @(posedge clk)
    begin
        case (counter)
            3'b001:
                z[31] <= z_sign;
            3'b111:
                z[31] <= z_sign;
        endcase
    end
endmodule

