module LIFObuffer(dataIn, RW, EN, Rst, Clk, EMPTY, FULL, dataOut) ;

    input [3:0] dataIn;

    input RW, EN, Rst, Clk;

    output EMPTY, FULL;

    output reg [3:0] dataOut;

    reg [3:0] stack_mem[0:3];
    reg [2:0] SP;

    assign EMPTY = (SP == 3'b100)? 1'b1 : 1'b0;

    assign FULL = (SP == 3'b000)? 1'b1 : 1'b0;
    always @(posedge Clk) begin 
        if(EN) begin
            if(Rst == 1'b1) begin
                SP = 3'b100;
                stack_mem[3] = 4'b0000;
                stack_mem[2] = 4'b0000;
                stack_mem[1] = 4'b0000;
                stack_mem[0] = 4'b0000;
            end
            else begin 
                if(RW == 1'b0 && FULL == 1'b0) begin
                    SP = SP-1;
                    stack_mem[SP] = dataIn;

                end
                else if (RW == 1'b1 && EMPTY == 1'b0) begin
                    dataOut = stack_mem[SP];
                    stack_mem[SP] = 4'b0000;
                    SP = SP+1;

                end
            end 
        end
    end
endmodule

