module pulse_detect(clk, rst_n, data_in, data_out) ;
    input clk ;
    input rst_n ;
    input data_in ;
    output data_out ;
    reg data_out ;
    reg[2:0] state ;
    always @ (posedge clk or negedge rst_n)
    begin
        if (~rst_n)
        begin
            state <= 3'b000 ;
            data_out <= 1'b0 ;
        end
        else
        begin
            case (state)
                3'b000 :
                begin
                    if (data_in == 1'b1)
                        state <= 3'b001 ;
                    else
                        state <= 3'b000 ;
                end
                3'b001 :
                begin
                    if (data_in == 1'b1)
                        state <= 3'b010 ;
                    else
                        state <= 3'b000 ;
                end
                3'b010 :
                begin
                    if (data_in == 1'b1)
                        state <= 3'b010 ;
                    else
                        state <= 3'b011 ;
                end
                3'b011 :
                begin
                    if (data_in == 1'b1)
                        state <= 3'b100 ;
                    else
                        state <= 3'b000 ;
                end
                3'b100 :
                begin
                    if (data_in == 1'b1)
                        state <= 3'b101 ;
                    else
                        state <= 3'b000 ;
                end
                3'b101 :
                begin
                    if (data_in == 1'b1)
                        state <= 3'b101 ;
                    else
                        state <= 3'b110 ;
                end
                3'b110 :
                begin
                    if (data_in == 1'b1)
                        state <= 3'b001 ;
                    else
                        state <= 3'b000 ;
                end
                default:
                    state <= 3'b000 ;
            endcase
            if ((state == 3'b011) || (state == 3'b101) || (state == 3'b110))
                data_out <= 1'b1 ;
            else
                data_out <= 1'b0 ;
        end
    end
endmodule

