module traffic_light(rst_n, clk, pass_request, red, yellow, green, clock);
`define idle 2'b00
`define s1_red 2'b01
`define s2_yellow 2'b10
`define s3_green 2'b11
    input rst_n;
    input clk;
    input pass_request;
    output red;
    output yellow;
    output green;
    output [7:0] clock;
    reg [7:0] cnt;
    reg [1:0] state;
    reg p_red, p_yellow, p_green;
    always @(posedge clk, negedge rst_n) begin
        if (!rst_n) begin
            state <= `idle;
        end else case (state)
            `idle: state <= `s1_red;
            `s1_red: begin
                if (cnt == 3'd3) begin
                    state <= `s3_green;
                end else begin
                    state <= `s1_red;
                end
            end
            `s2_yellow: begin
                if (cnt == 3'd3) begin
                    state <= `s1_red;
                end else begin
                    state <= `s2_yellow;
                end
            end
            `s3_green: begin
                if (cnt == 3'd3) begin
                    state <= `s2_yellow;
                end else begin
                    state <= `s3_green;
                end
            end
            default: state <= `idle;
        endcase
    end
    always @(posedge clk, negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 8'd10;
        end else if (pass_request && green) begin
            cnt <= 8'd10;
        end else if (!green && p_green) begin
            cnt <= 8'd60;
        end else if (!yellow && p_yellow) begin
            cnt <= 8'd5;
        end else if (!red && p_red) begin
            cnt <= 8'd10;
        end else begin
            if (cnt != 0) begin
                cnt <= cnt - 1'b1;
            end
        end
    end
    assign clock = cnt;
    always @(posedge clk, negedge rst_n) begin
        if (!rst_n) begin
            p_red <= 1'b0;
            p_yellow <= 1'b0;
            p_green <= 1'b0;
        end else begin
            p_red <= red;
            p_yellow <= yellow;
            p_green <= green;
        end
    end
    assign red = (state == `s1_red || state == `s2_yellow);
    assign yellow = (state == `s2_yellow);
    assign green = (state == `s3_green);
endmodule

