module alu (a, b, aluc, r, zero, carry, negative, overflow, flag) ;
    parameter ADD = 6'b100000;
    parameter ADDU = 6'b100001;
    parameter SUB = 6'b100010;
    parameter SUBU = 6'b100011;
    parameter AND = 6'b100100;
    parameter OR = 6'b100101;
    parameter XOR = 6'b100110;
    parameter NOR = 6'b100111;
    parameter SLT = 6'b101010;
    parameter SLTU = 6'b101011;
    parameter SLL = 6'b000000;
    parameter SRL = 6'b000010;
    parameter SRA = 6'b000011;
    parameter SLLV = 6'b000100;
    parameter SRLV = 6'b000110;
    parameter SRAV = 6'b000111;
    parameter LUI = 6'b001111;
    input [31:0] a, b ;
    input [5:0] aluc ;
    output [31:0] r ;
    output zero, carry, negative, overflow, flag;
    reg [32:0] res;

    wire signed [31:0] a, b;
    assign r = res[31:0] ;
    assign zero = (r == 32'b0)? 1'b1 : 1'b0;
    assign carry = res[32];
    assign negative = res[31];
    assign overflow = ((a[31] & b[31] & ~r[31]) | (~a[31] & ~b[31] & r[31])) ? 1 : 0;
    assign flag = (aluc == 6'b101010) ? res[31] : 1'bz;
    always @ (a, b, aluc) begin
        case (aluc)
            ADD : res = a + b;
            ADDU : res = a + b;
            SUB : res = a - b;
            SUBU : res = a - b;
            AND : res = a & b;
            OR : res = a | b;
            XOR : res = a ^ b;
            NOR : res = ~(a | b);
            SLT : res = $signed(a) < $signed(b) ;
            SLTU : res = a < b;
            SLL : res = b << a[4:0];
            SRL : res = b >> a[4:0];
            SRA : res = b >>> a[4:0];
            SLLV : res = b << a[4:0];
            SRLV : res = b >> a[4:0];
            SRAV : res = b >>> a[4:0];
            LUI : res = {a[15:0], 16'b0};
            default : res = 1'bz;
        endcase
    end
endmodule

