module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
) ;
    reg [15:0] div_opnd_abs;
    reg [15:0] div_mnml_abs;
    reg [15:0] SR;
    reg [7:0] NEG_DIVISOR;
    reg [3:0] cnt;
    reg start_cnt;
    wire [15:0] SUM;
    wire neg_out;
    wire cout;
    assign {neg_out, SUM} = SR[15:7] + NEG_DIVISOR;
    assign {cout, result} = SUM;
    always @(posedge clk)
    begin
        if (rst | !cnt) begin
            div_opnd_abs = 0;
            div_mnml_abs = 0;
            SR = 0;
            NEG_DIVISOR = 0;
            res_valid = 0;
            cnt = 0;
            start_cnt = 0;
        end
        else if (opn_valid & !res_valid) begin
            div_opnd_abs[7:0] = dividend[7:0];
            div_opnd_abs[15:8] = 0;
            div_mnml_abs[7:0] = divisor[7:0];
            div_mnml_abs[15:8] = 0;
            SR[15:0] = div_opnd_abs[15:0] << 1;
            if (sign) begin
                NEG_DIVISOR[7:0] = ~(div_mnml_abs[7:0]) + 8'h01;
            end
            else begin
                NEG_DIVISOR = ~div_mnml_abs + 1;
            end
            cnt = 4'h1;
            start_cnt = 1;
        end
        else if (start_cnt) begin
            if (cnt[3]) begin
                cnt = 4'h0;
                start_cnt = 0;
                res_valid = 1;
            end
            else begin
                cnt = cnt + 4'h1;
                if (neg_out) begin
                    SR[15:7] = SR[14:6];
                    SR[6:0] = SUM[6:0];
                end
                else begin
                    SR[15:7] = SR[14:6];
                    SR[6:0] = SUM[6:0];
                    SR = SR << 1;
                end
            end
        end
        else if (res_valid) begin
            res_valid = 0;
        end
    end
endmodule

