module comparator_4bit(A, B, A_greater, A_equal, A_less) ;
    input [3:0] A, B ;
    output A_greater, A_equal, A_less ;

    wire [3:0] sub_result ;
    wire c_out, c_in ;
    assign c_in = 0 ;
    wire c1, c2, c3 ;
    assign c1 = (A[0] & ~B[0]) ;
    assign c2 = (A[1] & ~B[1]) ;
    assign c3 = (A[2] & ~B[2]) ;
    assign c_out = (c1 | c2 | c3) ;
    assign sub_result[0] = ~(A[0] ^ B[0]) ^ c_in ;
    assign sub_result[1] = ~(A[1] ^ B[1]) ^ c_out ;
    assign sub_result[2] = ~(A[2] ^ B[2]) ^ c_out ;
    assign sub_result[3] = ~(A[3] ^ B[3]) ^ c_out ;

    assign A_greater = ~(sub_result[3] | sub_result[2]) & sub_result[1] ;
    assign A_equal = ~sub_result[3] & ~sub_result[2] & ~sub_result[1] & sub_result[0] ;
    assign A_less = sub_result[3] ;
endmodule

