module adder_bcd(A, B, Cin, Sum, Cout) ;
    input [3:0] A, B;
    input Cin;
    output [3:0] Sum;
    output Cout;
    reg [4:0] sum_temp;

    reg carry;
    always @(A, B, Cin)
    begin
        sum_temp = A + B + Cin;

        if (sum_temp > 9) 
            sum_temp = sum_temp + 6;

        if (sum_temp > 9)
            carry = 1;
        else
            carry = 0;
    end

    assign Sum = sum_temp[3:0];
    assign Cout = carry;
endmodule

