module sub_64bit (
    A, 
    B, 
    result, 
    overflow
) ;
input [63 : 0] A, B ;
output [63 : 0] result ;
output overflow ;
wire [63 : 0] neg_B ;
wire [63 : 0] temp_sum ;
wire A_sign, B_sign, temp_sum_sign ;
wire overflow_pos, overflow_neg ;
assign neg_B = ~B + 1'b1 ;
assign A_sign = A[63] ;
assign B_sign = B[63] ;
assign temp_sum = A + neg_B ;
assign temp_sum_sign = temp_sum[63] ;
assign overflow_pos = (A_sign == 1'b0) && (B_sign == 1'b1) && (temp_sum_sign == 1'b1) ;
assign overflow_neg = (A_sign == 1'b1) && (B_sign == 1'b0) && (temp_sum_sign == 1'b0) ;
assign overflow = overflow_pos || overflow_neg ;
assign result = temp_sum ^ {64{overflow}} ;
endmodule

