parameter S2 = 4'b0010;
parameter S3 = 4'b0011;
parameter S4 = 4'b0100;

always @(*) begin
    if (present_state == IDLE) begin
        if (data_in == 1) next_state = S1;
        else next_state = IDLE;
    end
    else if (present_state == S1) begin
        if (data_in == 0) next_state = S2;
        else next_state = S1;
    end
    else if (present_state == S2) begin
        if (data_in == 0) next_state = S3;
        else next_state = S1;
    end
    else if (present_state == S3) begin
        if (data_in == 1) next_state = S4;
        else next_state = IDLE;
    end
    else if (present_state == S4) begin
        if (data_in == 1) next_state = S1;
        else next_state = S2;
    end
end

always @(posedge clk or negedge reset_n) begin
    if (~reset_n) begin
        present_state <= IDLE;
        sequence_detected <= 0;
    end
    else begin
        present_state <= next_state;
        if (present_state == S4) sequence_detected <= 1;
        else sequence_detected <= 0;
    end
end
endmodule

