module LIFObuffer(dataIn, dataOut, RW, EN, Rst, Clk, EMPTY, FULL) ;
    input [3:0] dataIn ;
    input RW,EN,Rst,Clk ;
    output EMPTY, FULL;
    output [3:0] dataOut ;
    reg [3:0] stack_mem[3:0] ;

    reg [2:0] SP ;

    reg [3:0] Dout ;
    integer i ;
    always @ (posedge Clk) 
    begin
        if (EN)
        begin
            if (Rst)
            begin
                for(i=0;
 i<4;
 i=i+1)
                    stack_mem[i] <= 0 ;
                SP <= 4 ;
            end
            else
            begin
                if (RW) 
                begin
                    if (!EMPTY)
                    begin
                        Dout <= stack_mem[SP] ;
                        stack_mem[SP] <= 0 ;
                        SP <= SP+1 ;
                    end
                end
                else 
                begin
                    if (!FULL)
                    begin
                        SP <= SP-1 ;
                        stack_mem[SP] <= dataIn ;
                    end
                end
            end
        end
    end
    assign EMPTY = (SP==4) ? 1 : 0 ;
    assign FULL = (SP==0) ? 1 : 0 ;
    assign dataOut = Dout ;
endmodule

