module pulse_detect(clk, rst_n, data_in, data_out) ;
    input clk, rst_n, data_in ;
    output reg data_out ;

    reg [2:0] state ;

    parameter s0 = 3'b000, s1 = 3'b001, s2 = 3'b010, s3 = 3'b011, s4 = 3'b100 ;

    always @ (posedge clk or negedge rst_n) begin
        if (~rst_n) begin
            state <= s0 ;
            data_out <= 1'b0 ;
        end else begin
            case (state)
                s0: begin
                    if (data_in) state <= s1 ;
                end
                s1: begin
                    if (~data_in) state <= s2 ;
                end
                s2: begin
                    if (data_in) state <= s3 ;
                end
                s3: begin
                    if (~data_in) state <= s4 ;
                end
                s4: begin
                    if (data_in) state <= s0 ;
                    else state <= s0 ;
                end
                default: state <= s0 ;
            endcase
        end
    end

    always @ (posedge clk or negedge rst_n) begin
        if (~rst_n) data_out <= 1'b0 ;
        else begin
            if (state == s4) data_out <= 1'b1 ;
            else data_out <= 1'b0 ;
        end
    end
endmodule

