module traffic_light(input rst_n, input clk, input pass_request, output[7:0] clock, output red, output yellow, output green);

  parameter idle = 2'b00, s1_red = 2'b01, s2_yellow = 2'b10, s3_green = 2'b11;
  reg[1:0] state, next_state;
  reg[7:0] cnt;
  reg p_red, p_yellow, p_green;
  assign clock = cnt;
  assign red = p_red;
  assign yellow = p_yellow;
  assign green = p_green;
  always @(posedge clk or negedge rst_n)
    if(!rst_n)
      state <= idle;
    else
      state <= next_state;
  always @*
    case(state)
      idle: next_state = s1_red;
      s1_red:
        if(cnt == 3'd0) next_state = s3_green;
        else next_state = s1_red;
      s2_yellow:
        if(cnt == 3'd0) next_state = s1_red;
        else next_state = s2_yellow;
      s3_green:
        if(cnt == 3'd0) next_state = s2_yellow;
        else next_state = s3_green;
      default: next_state = idle;
    endcase
  always @(posedge clk or negedge rst_n)
    if(!rst_n) cnt <= 8'd10;
    else if(pass_request && p_green) cnt <= 8'd10;
    else if(!p_green && p_yellow && !p_red) cnt <= 8'd60;
    else if(!p_yellow && p_red) cnt <= 8'd5;
    else if(cnt != 8'd0) cnt <= cnt - 1'd1;
    else cnt <= cnt;
  always @(posedge clk or negedge rst_n)
    if(!rst_n) begin
      p_red <= 1'b0;
      p_yellow <= 1'b0;
      p_green <= 1'b0;
    end
    else begin
      p_red <= (state == s1_red) ? 1'b1 : 1'b0;
      p_yellow <= (state == s2_yellow) ? 1'b1 : 1'b0;
      p_green <= (state == s3_green) ? 1'b1 : 1'b0;
    end
endmodule

