        case (present_state)
            IDLE: begin
                if (data_in == 1)
                    next_state = S1;
                else
                    next_state = IDLE;
            end
            S1: begin
                if (data_in == 0)
                    next_state = S2;
                else
                    next_state = S1;
            end
            S2: begin
                if (data_in == 0)
                    next_state = S3;
                else
                    next_state = S1;
            end
            S3: begin
                if (data_in == 1)
                    next_state = S4;
                else
                    next_state = IDLE;
            end
            S4: begin
                if (data_in == 0)
                    next_state = S2;
                else
                    next_state = S1;
            end
            default: begin
                next_state = IDLE;
            end
        endcase
    end

    always @(posedge clk or negedge reset_n) begin
        if (reset_n == 0)
            present_state <= IDLE;
        else
            present_state <= next_state;
    end

    always @(posedge clk or negedge reset_n) begin
        if (reset_n == 0)
            sequence_detected <= 0;
        else if (present_state == S4)
            sequence_detected <= 1;
        else
            sequence_detected <= 0;
