module LIFObuffer (
    input [3:0] dataIn,
    input RW,
    input EN,
    input Rst,
    input Clk,
    output EMPTY,
    output FULL,
    output reg [3:0] dataOut
) ;
reg [3:0] stack_mem [0:3] ;
reg [2:0] SP ;

reg [3:0] temp_var ;
always @ (posedge Clk)
begin
    if(EN)
    begin
        if(Rst)
        begin
            SP = 4;
            temp_var = 0;
            stack_mem[0] = temp_var;
            stack_mem[1] = temp_var;
            stack_mem[2] = temp_var;
            stack_mem[3] = temp_var;
        end
        else
        begin
            if (SP == 0)
            begin
            dataOut <= stack_mem[SP];

            stack_mem[SP] <= dataIn;
            SP = SP + 4'd1;
            end
            else if(RW == 0 && SP != 4'd0)
            begin
            SP = SP - 4'd1;
            stack_mem[SP] <= dataIn;
            end
            else if(RW == 1 && SP != 4'd0)
            begin
            dataOut <= stack_mem[SP];
            stack_mem[SP] <= 4'd0;
            SP = SP + 4'd1;
            end
        end
    end
end
assign EMPTY = (SP == 0) ? 1 : 0 ;
assign FULL = (SP == 4) ? 1 : 0 ;
endmodule

