        if (~rst_n) begin
            state <= 3'b000;
            data_out <= 0;
        end
        else begin
            case (state)
                3'b000: begin
                    if (data_in == 0) begin
                        state <= 3'b000;
                    end
                    else begin
                        state <= 3'b001;
                    end
                end
                3'b001: begin
                    if (data_in == 0) begin
                        state <= 3'b010;
                    end
                    else begin
                        state <= 3'b001;
                    end
                end
                3'b010: begin
                    if (data_in == 0) begin
                        state <= 3'b011;
                    end
                    else begin
                        state <= 3'b001;
                    end
                end
                3'b011: begin
                    if (data_in == 0) begin
                        state <= 3'b100;
                    end
                    else begin
                        state <= 3'b001;
                    end
                end
                3'b100: begin
                    if (data_in == 0) begin
                        state <= 3'b000;
                    end
                    else begin
                        state <= 3'b001;
                    end
                end
                default: state <= 3'b000;
            endcase
            if (state[0] == 1'b1) begin
                data_out <= 1;
