    if (!rst_n) state <= `idle;
    else case (state)
        `idle : state <= `s1_red;
        `s1_red: 
            if (cnt == 0) state <= `s3_green;
            else state <= `s1_red;
        `s2_yellow : 
            if (cnt == 0) state <= `s1_red;
            else state <= `s2_yellow;
        `s3_green : 
            if (cnt == 0) state <= `s2_yellow;
            else state <= `s3_green;
    endcase
