    if (!rst_n) cnt <= 8'd10;
    else if (pass_request && green) cnt <= 8'd10;
    else if (!green && p_green) cnt <= 8'd60;
    else if (!yellow && p_yellow) cnt <= 8'd5;
    else if (!red && p_red) cnt <= 8'd10;
    else if (cnt == 8'd10 && green && !p_green) cnt <= 8'd60;

    else cnt <= cnt - 8'd1;
