    parameter XOR = 6'b100110;
    parameter NOR = 6'b100111;
    parameter SLT = 6'b101010;
    parameter SLTU = 6'b101011;
    parameter SLL = 6'b000000;
    parameter SRL = 6'b000010;
    parameter SRA = 6'b000011;
    parameter SLLV = 6'b000100;
    parameter SRLV = 6'b000110;
    parameter SRAV = 6'b000111;
    parameter LUI = 6'b001111;
    reg [32:0] res;
    wire [31:0] b1 = aluc[0] ? ~b : b;

    wire [32:0] sum = a + b1 + aluc[0];
    wire [31:0] a32signed = a;
    wire [31:0] b32signed = b;
    assign { carry, overflow } = (a32signed[31] == b32signed[31]) ? sum[32:31] : (sum[32] ? 2'b01 : 2'b00);
    always @(*) begin
        case (aluc)
        ADD: res = a + b;
        ADDU: res = a + b;
        SUB: res = a - b;
        SUBU: res = a - b;
        AND: res = a & b;
        OR: res = a | b;
