module radix2_div (clk, rst, sign, dividend, divisor, opn_valid, res_valid, result) ;
	parameter 			 WIDTH = 8;
	parameter             INPUT_WIDTH = 16;
	input                 clk, rst;
	input                 sign;
	input   [WIDTH-1:0]   dividend, divisor;
	input                 opn_valid;
	output  reg           res_valid;
	output  [INPUT_WIDTH-1:0] result;
	reg                   res_reg;
	reg                   start_cnt;
	reg  [$clog2(WIDTH):0]  cnt;
	reg  [INPUT_WIDTH-1:0]  SR, NEG_DIVISOR;
	wire [INPUT_WIDTH-1:0]  op_sub, shift_sub, shift_add;
	wire                   cout_sub;
	wire                   mux_sel;
	wire [INPUT_WIDTH-1:0] abs_dividend, abs_divisor;
	assign abs_dividend = sign ? dividend : dividend;
	assign abs_divisor  = sign ? divisor : divisor;

	assign {cout_sub, op_sub} = SR - NEG_DIVISOR;
	assign mux_sel = SR[WIDTH] ? 1'b0 : 1'b1;
	assign shift_sub = (cout_sub ? SR : op_sub) <<< 1;
	assign shift_add = ((~cout_sub) ? SR : op_sub) <<< 1;

	always @(posedge clk) begin
		if (rst || cnt >= WIDTH) begin
			cnt <= 1'b0;
			start_cnt <= 1'b0;
		end else if (opn_valid) begin
			cnt <= 1'b1;
			start_cnt <= 1'b1;
		end else if (start_cnt) begin
			cnt <= cnt + 1'b1;
		end
	end

	always @(posedge clk) begin
		if (rst) begin
			SR <= {8{1'b0}};
			NEG_DIVISOR <= {8{1'b0}};
		end else if (opn_valid) begin
			SR <= {abs_dividend, {WIDTH{1'b0}}};
			NEG_DIVISOR <= {~abs_divisor, {WIDTH{1'b0}}};
		end else if (start_cnt) begin
			if (cnt >= WIDTH) begin
				cnt <= 1'b0;
				start_cnt <= 1'b0;
				SR <= SR <<< 1;
				SR[0] <= SR[WIDTH];
				SR[WIDTH] <= SR[WIDTH];
			end else begin
				SR <= SR <<< 1;
				SR[0] <= shift_sub[WIDTH];
				SR[WIDTH] <= shift_add[WIDTH];
			end
		end
	end

	assign result = SR;

	always @(posedge clk) begin
		if (rst || cnt == 1) begin
			res_valid <= 1'b0;
			res_reg <= 1'b0;
		end else if (cnt > WIDTH) begin
			res_valid <= 1'b0;
			res_reg <= 1'b0;
		end else begin
			res_valid <= 1'b1;
			res_reg <= 1'b1;
		end
	end
endmodule

