module adder_bcd(A, B, Cin, Sum, Cout) ;
    input [3:0] A, B ;
    input Cin ;
    output [3:0] Sum ;
    output Cout ;
    reg [4:0] temp ;
    always @(A or B or Cin)
    begin
        temp = A + B + Cin ;
        if(temp > 4'b1001)
        begin
            temp = temp + 4'b0110 ;
        end
    end
    assign {Cout, Sum} = temp ;
