module float_multi(
    input         clk,
    input         rst,
    input  [31:0] a,
    input  [31:0] b,
    output [31:0] z
    )
    ;
    reg [2:0] counter;
    reg [23:0] a_mantissa, b_mantissa, z_mantissa;
    reg [23:0] product;
    reg [9:0] a_exponent, b_exponent, z_exponent;
    reg a_sign, b_sign, z_sign;
    reg guard_bit, round_bit, sticky;
    always @(posedge clk)
    begin
        if(rst)
        begin
            counter     <= 0;
        end
        else
        begin
            case(counter)
                0: begin 
                    a_mantissa  <= {1'b1, a[22:0]};
                    a_exponent  <= a[30:23];
                    a_sign      <= a[31];
                    b_mantissa  <= {1'b1, b[22:0]};
                    b_exponent  <= b[30:23];
                    b_sign      <= b[31];
                    product     <= a_mantissa * b_mantissa;
                    counter     <= counter + 1;
                end
                1: begin 
                    if((&a_exponent) || (&b_exponent)) 
                    begin
                        z_exponent  <= 8'b11111111;
                        z_mantissa  <= 24'b0;
                        z_sign      <= a_sign ^ b_sign;
                        counter     <= 3;

                    end
                    else
                    begin
                        if(product[49]) 
                        begin
                            z_exponent  <= 10'b0;
                            z_mantissa  <= 24'b0;
                            z_sign      <= a_sign ^ b_sign;
                            counter     <= 3;

                        end
                        else
                        begin
                            z_exponent  <= a_exponent + b_exponent - 126;
                            if(product[48]) 
                            begin
                                z_mantissa  <= product[47:24];
                                guard_bit   <= product[23];
                                round_bit   <= product[22];
                                sticky      <= (|product[21:0]);
                            end
                            else 
                            begin
                                z_mantissa  <= product[45:22];
                                guard_bit   <= product[21];
                                round_bit   <= product[20];
                                sticky      <= (|product[19:0]);
                            end
                            counter     <= counter + 1;
                        end
                    end
                end
                2: begin 
                    if(guard_bit && (round_bit || sticky || z_mantissa[0]))
                        z_mantissa <= z_mantissa + 1;
                    counter <= counter + 1;
                end
                3: begin 
                    z_sign <= a_sign ^ b_sign;
                    if(&z_exponent) 
                    begin
                        z_exponent  <= 8'b11111111;
                        z_mantissa  <= 24'b0;
                    end
                    else if(z_exponent[7]) 
                    begin
                        z_exponent  <= 10'b0;
                        z_mantissa  <= 24'b0;
                    end
                end
            endcase
        end
    end
    assign z = {z_sign, z_exponent, z_mantissa};
