module LIFObuffer(
    dataIn, 
    RW, 
    EN, 
    Rst, 
    Clk, 
    EMPTY, 
    FULL, 
    dataOut
) ;

    input [3:0] dataIn ;

    input RW, EN, Rst, Clk ;

    output EMPTY, FULL ;

    output [3:0] dataOut ;

    reg [3:0] stack_mem [0:3] ;

    reg [2:0] SP ;

    reg [3:0] dataOut ;
    wire FULL ;
    wire EMPTY ;
    assign EMPTY = (SP == 4) ;

    assign FULL = (SP == 0) ;
    always @ (posedge Clk) begin
        if (EN) begin
            if (Rst) begin
                SP <= 4;

                $display("Stack is cleared");
                stack_mem[0] = 0 ;
                stack_mem[1] = 0 ;
                stack_mem[2] = 0 ;
                stack_mem[3] = 0 ;
            end
            else begin
                if (!FULL && !RW) begin
                    stack_mem[SP] <= dataIn ;

                    SP <= SP - 1'b1 ;

                    $display("Pushed %d onto the stack\n SP is %d", dataIn, SP);
                end
                else if (!EMPTY && RW) begin
                    dataOut <= stack_mem[SP];
                    stack_mem[SP] <= 0;
                    SP <= SP + 1'b1;

                    $display("Popped %d from stack. Current SP is %d", stack_mem[SP], SP);
                end
            end
        end
    end
endmodule

