reg [7:0] cnt;
reg p_red, p_yellow, p_green;

always @ (posedge clk or negedge rst_n)
begin
    if (!rst_n) state <= `IDLE;
    else state <= next_state;
end

always @ (state or cnt or pass_request)
begin
    if (state == `IDLE)
        begin
            next_state = `s1_red;
        end
    else if (state == `s1_red)
        begin
            if (cnt == 7'd3)
                next_state = `s3_green;
            else
                next_state = `s1_red;
        end
    else if (state == `s2_yellow)
        begin
            if (cnt == 7'd3)
                next_state = `s1_red;
            else
                next_state = `s2_yellow;
        end
    else if (state == `s3_green)
        begin
            if (cnt == 7'd3)
                next_state = `s2_yellow;
            else
                next_state = `s3_green;
        end
end

always @(posedge clk or negedge rst_n)
begin
    if (!rst_n)
        begin
            p_red <= 1'b0;
            p_yellow <= 1'b0;
            p_green <= 1'b0;
        end
    else
        begin
            p_red <= red;
            p_yellow <= yellow;
            p_green <= green;
        end
end
assign clock = cnt;

always @ (posedge clk or negedge rst_n)
begin
    if (!rst_n) cnt <= `MODULO;
    else if (pass_request && green) cnt <= 7'd10;
    else if (~green && p_green) cnt <= `MODULO;
    else if (~yellow && p_yellow) cnt <= 7'd5;
    else if (~red && p_red) cnt <= 7'd10;
    else cnt <= cnt - 1'b1;
end

always @(posedge clk or negedge rst_n)
begin
    if (!rst_n) begin
        red <= 1'b0;
        green <= 1'b0;
        yellow <= 1'b0;
    end
    else
        case (state)
        `s1_red: begin
            red <= 1'b1;
            green <= 1'b0;
            yellow <= 1'b0;
        end
        `s2_yellow: begin
            red <= 1'b0;
            green <= 1'b0;
            yellow <= 1'b1;
        end
        `s3_green: begin
            red <= 1'b0;
            green <= 1'b1;
            yellow <= 1'b0;
        end
        default: begin
            red <= 1'b0;
            green <= 1'b0;
            yellow <= 1'b0;
        end
        endcase
