module radix2_div (

    clk,
    rst,
    sign,
    dividend,
    divisor,
    opn_valid,

    res_valid,
    result
) ;

input clk, rst, opn_valid, sign ;
input [7:0] dividend, divisor ;

output reg res_valid ;
output reg [15:0] result ;

reg [15:0] dividend_1 ;
reg [7:0] divisor_1 ;
reg [15:0] SR;
reg cnt, start_cnt;
reg [15:0] NEG_DIVISOR ;
reg [16:0] sum;

wire MSB_RES;
wire [15:0] shifted_divisor, remainder, quotient;
wire [15:0] negetive_remainder;
wire [16:0] input_to_add;
wire [15:0] new_SR ;


assign remainder = SR[15:0] ;
assign quotient = SR[15:8] ;
assign MSB_RES = ~(~sum[16] | sign) ;

assign negetive_remainder = ~remainder ;
assign input_to_add = { MSB_RES, sign ? remainder : negetive_remainder };
assign {sum[16], sum[15:0]} = {1'b0, SR[15:0]} + input_to_add;


assign new_SR = {SR[14:0], ~sum[16] };


always @ (*)
begin
    if(rst)
    begin
        result <= {8'h00, 8'h00};
        res_valid <= 1'b0;
    end
    else if(cnt & ~res_valid)
    begin
        if(~remainder)
            result <= {8'h00, quotient};
        else 
            result <= {remainder, quotient};
        res_valid <= 1'b1;
    end
    else 
    begin
        res_valid <= 1'b0;
    end
end

always @(posedge clk)
begin
    if(opn_valid & ~res_valid)
    begin
        dividend_1 <= {{1'b0, dividend}, {8'b00000001}};

        divisor_1 <= {1'b0, divisor};

        NEG_DIVISOR <= {{15{divisor[7]}}, divisor};

        SR <= {{8{dividend_1[15]}}, dividend_1[15:0]};
        cnt <= 1'b0;
        start_cnt <= 1'b1;

    end 
end

always @(posedge clk)
begin
    if (rst)
        cnt <= 1'b0;
    else if (start_cnt)
        cnt <= cnt + 1'b1;
end

always @(posedge clk)
begin
    if (start_cnt)
    begin
        if (cnt == 1'b1)
            start_cnt <= 1'b0;
        if (cnt == 8)
        begin
            cnt <= 1'b0;
            start_cnt <= 1'b0;
        end
        SR <= new_SR;
    end
end
endmodule

