module adder_bcd(
    input [3:0] A,
    input [3:0] B,
    input Cin,
    output [3:0] Sum,
    output Cout
);
    wire [3:0] raw_sum;
    wire bcd_carry;
    assign {bcd_carry, raw_sum} = A + B + Cin;
    assign Sum = (bcd_carry | raw_sum > 4'b1001) ? (raw_sum + 4'b0110) : raw_sum;
    assign Cout = (bcd_carry | raw_sum > 4'b1001);
endmodule

