module fixed_point_subtractor #(parameter Q = 24, parameter N = 32)
(
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output wire [N-1:0] c
) ;
reg [N-1:0] res;
reg [2*N-1:0] big_a, big_b;

assign c = res;
always @(a, b)
begin
    big_a = {a, {(N){1'b0}}};
    big_b = {b, {(N){1'b0}}};
    if (a[N-1] == b[N-1]) 
    begin
        res = a[N-1] ? ((big_b - big_a) >> Q) : ((big_a - big_b) >> Q);
    end
    else 
    begin
        res = (a[N-1] == 1'b1) ? 
        (~((~big_a + big_b) >> Q)) : 
        ~((~big_b + big_a) >> Q);

    end
    if (res == 0)
    begin
        res[N-1] = 1'b0;
    end
end
endmodule

