                if ((a_mantissa[23:1] == 23'b0) || (b_mantissa[23:1] == 23'b0)) begin
                    z_sign <= 0;
                    z_exponent <= 0;
                    z_mantissa <= 0;
                    counter <= 5'b11111;
                end
                else begin
                    counter <= counter + 1;
                end
            end
            5'b00011: begin
                if (a_exponent + b_exponent > 127) begin
                    z_sign <= 0;
                    z_exponent <= 0;
                    z_mantissa <= 0;
                    counter <= 5'b11111;
                end
                else begin
                    counter <= counter + 1;
                end
            end
            5'b00100: begin
                if (a_exponent + b_exponent > 127) begin
                    z_sign <= 0;
                    z_exponent <= 0;
                    z_mantissa <= 0;
                    counter <= 5'b11111;
                end
                else begin
                    if (a_mantissa[23:1] >= 23) begin
                        a_mantissa <= a_mantissa >> 1;
                        a_exponent <= a_exponent + 1;
                    end
                    if (b_mantissa[23:1] >= 23) begin
                        b_mantissa <= b_mantissa >> 1;
                        b_exponent <= b_exponent + 1;
                    end
                    counter <= 5'b00110;
                end
            end
            5'b00110: begin
                product <= a_mantissa * b_mantissa;
                guard_bit <= product[24] | product[23];
                round_bit <= product[22];
                sticky <= product[21] | product[20] | product[19] | product[18] | product[17] | product[16] | product[15] | product[14] | product[13] | product[12] | product[11] | product[10] | product[9] | product[8] | product[7] | product[6] | product[5] | product[4] | product[3] | product[2] | product[1] | product[0];
                counter <= counter + 1;
            end
            5'b00111: begin
                if (guard_bit & (round_bit | sticky)) begin
                    product <= product + 1;
                end
                z_sign <= a_sign ^ b_sign;
                z_mantissa <= product[22:0];
                z_exponent <= a_exponent + b_exponent - 127;
