  assign s0_result = (A[63] & !B[63] & !s0_overflow) | (!A[63] & B[63] & s0_overflow);
  assign s1_overflow = (A[63] & !B[63] & !result[63]) | (!A[63] & B[63] & result[63]);
  assign overflow = s0_result ? 1'b1 : 1'b0;
endmodule

