    input  [3:0]     d ;
    output           valid_out ;
    output           dout ;
    reg    [3:0]     data ;
    wire   [3:0]     d_next = data[1:0] + data[3:2] ;
    reg              valid ;
    reg    [1:0]     cnt = 0 ;
    wire             cnt_inc = (cnt == 3) ? 1 : 0 ;
    wire             cnt_rst = (cnt == 3) ? 1 : 0 ;
    assign valid_out = valid ;
    assign dout = data[3] ;
