    always @(posedge clk or negedge rst_n)
        if (!rst_n)
            valid <= 0 ;
        else
            valid <= valid_next ;
    assign valid_next = cnt_inc ? 1 : 0 ;
    always @(posedge clk or negedge rst_n)
        if (!rst_n)
            cnt <= 0 ;
        else
            cnt <= cnt_next ;
    assign cnt_next = cnt_rst ? 0 : cnt + 1 ;
