module alu (input [31:0] a, b, input [5:0] aluc, output reg [31:0] r) ;
	wire signed [31:0] signed_a, signed_b;
	reg signed [31:0] res;
	assign signed_a = a;
	assign signed_b = b;
	assign {negative, overflow, carry, r} = res;

	always @ (a or b or aluc)
	begin
		case (aluc)
			6'b100000: res = a + b;

			6'b100001: res = a + b;

			6'b100010: res = a - b;

			6'b100011: res = a - b;

			6'b100100: res = a & b;

			6'b100101: res = a | b;

			6'b100110: res = a ^ b;

			6'b100111: res = ~(a | b);

			6'b101010: res = signed_a < signed_b;

			6'b101011: res = a < b;

			6'b000000: res = a << (a[4:0] & 32'h1f);

			6'b000010: res = a >> (a[4:0] & 32'h1f);

			6'b000011: res = a >>> (a[4:0] & 32'h1f);

			6'b000100: res = b << (a[4:0] & 32'h1f);

			6'b000110: res = b >> (a[4:0] & 32'h1f);

			6'b000111: res = b >>> (a[4:0] & 32'h1f);

			6'b001111: res = {a[15:0], 16'h0000};

			default: res = 32'hzzzz;

		endcase
	end
endmodule

