module multi_16bit(clk, rst_n, start, ain, bin, yout, done) ;
    input clk, rst_n, start;
    input [15:0] ain, bin;
    output [31:0] yout;
    output done;

    reg [4:0] i;
    always @(posedge clk or negedge rst_n)
    begin
        if (!rst_n)
            i <= 0;
        else if (start && i < 17)
            i <= i + 1;
        else if (!start)
            i <= 0;
    end
    assign done = (i == 16);

    reg [15:0] areg, breg;
    reg [31:0] yout_r;
    always @(posedge clk or negedge rst_n)
    begin
        if (!rst_n)
            {areg, breg, yout_r} <= 'd0;
        else begin
            if (start) begin
                if (i == 0) begin
                    areg <= ain;
                    breg <= bin;
                    yout_r <= 0;
                end
                else if (i < 17) begin
                    if (areg[i-1])
                        yout_r <= yout_r + (breg << (i-1)) | 0;
                end
            end
        end
    end
    assign yout = yout_r;
endmodule

