module fsm(
    input IN, 
    input CLK, 
    input RST, 
    output reg MATCH
    );
reg [3:0] cnt;
reg [3:0] last1;
reg [3:0] last2;
reg [3:0] last3;
reg [3:0] last4;
reg [3:0] last5;
