module LIFObuffer(dataIn, RW, EN, Rst, Clk, EMPTY, FULL, dataOut) ;
    input[3:0] dataIn;
    input RW, EN, Rst, Clk;
    output EMPTY, FULL;
    output [3:0] dataOut;
    wire [3:0] dataIn;
    reg[3:0] dataOut;
    reg[3:0] stack_mem[3:0];

    reg [1:0] SP;


    assign EMPTY = (SP == 2'b10) ? 1'b1 : 1'b0;

    assign FULL = (SP == 2'b01) ? 1'b1 : 1'b0;

    always @ (posedge Clk)
    begin 
        if(EN == 1)
        begin
            if(Rst == 1)
            begin
                SP = 2'b10;
                stack_mem[0] = 4'b0000;
                stack_mem[1] = 4'b0000;
                stack_mem[2] = 4'b0000;
                stack_mem[3] = 4'b0000;
            end
            else 
            begin
                if(!FULL && !RW) 
                begin
                    SP = SP - 1;
                    stack_mem[SP] = dataIn;
                end
                else if(!EMPTY && RW) 
                begin
                    dataOut = stack_mem[SP];
                    stack_mem[SP] = 4'b0000;
                    SP = SP + 1;
                end
            end
        end
    end
endmodule

