module traffic_light
(
    input rst_n,
    input clk,
    input pass_request,
    output [7:0] clock,
    output red,
    output yellow,
    output green
);
localparam idle = 2'b00;
localparam s1_red = 2'b01;
localparam s2_yellow = 2'b10;
localparam s3_green = 2'b11;
reg [7:0] cnt;
reg [1:0] state, nstate;
reg p_red, p_yellow, p_green;
assign clock = cnt;
assign red = p_red;
assign yellow = p_yellow;
assign green = p_green;
always @ (posedge clk or negedge rst_n) begin
    if (!rst_n) state <= idle;
    else state <= nstate;
end
always @ (*) begin
    case (state)
        idle: nstate = s1_red;
        s1_red: if (cnt > 3'd2) nstate = s3_green;
 else nstate = s1_red;
        s2_yellow: if (cnt > 3'd2) nstate = s1_red;
 else nstate = s2_yellow;
        s3_green: if (cnt > 3'd2) nstate = s2_yellow;
 else nstate = s3_green;
        default: nstate = idle;
    endcase
end
always @ (posedge clk or negedge rst_n) begin
    if (!rst_n) cnt <= 8'd10;
    else if (pass_request & p_green) cnt <= 8'd10;
    else if (!p_green & p_yellow) cnt <= 8'd60;
    else if (!p_yellow & p_red) cnt <= 8'd5;
    else if (!p_red & p_green) cnt <= 8'd10;
    else cnt <= cnt - 1'b1;
end
always @ (posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        p_red <= 1'b0;
        p_yellow <= 1'b0;
        p_green <= 1'b0;
    end
    else begin
        p_red <= red;
        p_yellow <= yellow;
        p_green <= green;
    end
end
endmodule

