module edge_detect (clk, rst_n, a, rise, down) ;
    input clk;
    input rst_n;
    input a;
    output rise;
    output down;
    reg rise;
    reg down;
    reg a_reg;
    always @(posedge clk or negedge rst_n)
    begin
        if (~rst_n) begin
            a_reg <= 0;
            rise <= 0;
            down <= 0;
        end
        else begin
            a_reg <= a;
            if (a_reg == 1 && a == 0) begin
                down <= 1;
                rise <= 0;
            end
            else if (a_reg == 0 && a == 1) begin
                down <= 0;
                rise <= 1;
            end
            else begin
                down <= 0;
                rise <= 0;
            end
        end
    end
endmodule

