module alu(input [31:0] a, b, input [5:0] aluc, output [31:0] r, output zero, carry, negative, overflow, flag) ;
    parameter ADD = 6'b100000;
    parameter ADDU = 6'b100001;
    parameter SUB = 6'b100010;
    parameter SUBU = 6'b100011;
    parameter AND = 6'b100100;
    parameter OR = 6'b100101;
    parameter XOR = 6'b100110;
    parameter NOR = 6'b100111;
    parameter SLT = 6'b101010;
    parameter SLTU = 6'b101011;
    parameter SLL = 6'b000000;
    parameter SRL = 6'b000010;
    parameter SRA = 6'b000011;
    parameter SLLV = 6'b000100;
    parameter SRLV = 6'b000110;
    parameter SRAV = 6'b000111;
    parameter LUI = 6'b001111;
    wire signed [31:0] sa, sb;
    assign sa = a;
    assign sb = b;
    reg [32:0] res;
    assign r[31:0] = res[31:0];
    assign flag = (aluc == 6'b101000) ? res[31:31] : 1'bz;

    assign zero = ~|r[31:0];
    assign carry = res[32:32];
    assign negative = r[31:31];
    assign overflow = ((a[31:31] == b[31:31]) && (r[31:31] != a[31:31])) ? 1'b1 : 1'b0;
    always @(*) begin
        case(aluc[5:0])
            ADD, ADDU: begin
                res[31:0] = $signed(a) + $signed(b);
                res[32] = 0;
            end
            SUB, SUBU: begin
                res[31:0] = $signed(a) - $signed(b);
                res[32] = 0;
            end
            AND: begin
                res[31:0] = $signed(a) & $signed(b);
                res[32] = 0;
            end
            OR: begin
                res[31:0] = $signed(a) | $signed(b);
                res[32] = 0;
            end
            XOR: begin
                res[31:0] = $signed(a) ^ $signed(b);
                res[32] = 0;
            end
            NOR: begin
                res[31:0] = ~($signed(a) | $signed(b));
                res[32] = 0;
            end
            SLT: begin
                res[31:0] = $signed(a) < $signed(b) ? 32'b1 : 32'b0;
                res[32] = 0;
            end
            SLTU: begin
                res[31:0] = a < b ? 32'b1 : 32'b0;
                res[32] = 0;
            end
            SLL: begin
                res[31:0] = b << a[4:0];
                res[32] = 0;
            end
            SRL: begin
                res[31:0] = b >> a[4:0];
                res[32] = 0;
            end
            SRA: begin
                res[31:0] = sb >>> a[4:0];
                res[32] = 0;
            end
            SLLV: begin
                res[31:0] = b << sa[4:0];
                res[32] = 0;
            end
            SRLV: begin
                res[31:0] = b >> sa[4:0];
                res[32] = 0;
            end
            SRAV: begin
                res[31:0] = sb >>> sa[4:0];
                res[32] = 0;
            end
            LUI: begin
                res[31:0] = {a[15:0], 16'b0};
                res[32] = 0;
            end
            default: begin
                res[31:0] = 32'bz;
                res[32] = 1'bz;
            end
        endcase
    end
endmodule

