module radix2_div
(
    input clk, rst,
    input  sign,
    input  [7:0] dividend,
    input  [7:0] divisor,
    input  opn_valid,
    output reg res_valid,
    output reg [15:0] result
) ;
    reg  [7:0] dividend_r, divisor_r, NEG_DIVISOR;

    reg  [7:0] SR;
    reg  [3:0] cnt;
    reg  start_cnt;
    wire [7:0] sum1;
    wire cout;
    wire carry;
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            dividend_r <= 0;
            divisor_r <= 0;
            NEG_DIVISOR <= 0;
            SR <= 0;
            res_valid <= 0;
            result <= 0;
            cnt <= 0;
            start_cnt <= 0;
        end 
        else if (opn_valid & !res_valid) begin
            dividend_r <= dividend;
            divisor_r <= divisor;
            NEG_DIVISOR <= {1'b0, ~divisor} + 8'b1;
            if (sign) begin
                if (dividend[7]==1) begin
                    SR <= {1'b0, ~dividend} + 8'b1;
                end
                else SR <= {1'b0, dividend};
            end 
            else SR <= {1'b0, dividend};
            cnt <= 1;
            start_cnt <= 1;
        end
        else if (start_cnt) begin
            if (cnt[3] == 1) begin
                cnt <= 0;
                start_cnt <= 0;
                if (sign) begin
                    if (dividend[7]==1) begin
                        SR <= {8'b0, ~dividend} + 8'b1;
                    end
                    else SR <= {8'b0, dividend};
                end 
                else SR <= {8'b0, dividend};
            end
            else cnt <= cnt + 1;
            {carry, sum1} <= SR[7:0] + NEG_DIVISOR;
            if (carry) begin
                SR[7:0] <= {SR[6:0], 1'b0};
            end 
            else 
            begin
                SR[7:0] <= {sum1[6:0], 1'b1};
            end
        end
    end
    always @(posedge clk or posedge rst) begin
        if (rst) res_valid <= 0;
        else if ((!cnt & !res_valid) || (cnt == 4'd8 && !res_valid)) res_valid <= 1;
        else if (!cnt) res_valid <= 0;
    end
    always @(posedge clk or posedge rst) begin
        if (rst) result <= 0;
        else if (res_valid & !result) result <= {SR[7:0], 8'b0};
        else result <= 0;
    end
endmodule

