module accu(
    clk, rst_n, data_in, valid_in, 
    valid_out, data_out
    ) ;
parameter WAIT = 2'b01;
parameter RUN = 2'b10;
parameter WAIT_OUT = 2'b11;
input   clk;

input   rst_n;
input   [7:0]  data_in;
input         valid_in;
output  valid_out;
output  [9:0]  data_out;
reg     valid_out;
reg     [1:0]  state, state_next;
reg     [3:0]  count, count_next;
reg     [9:0]  data_out, data_out_next;
always @*
begin
    case (state)
        WAIT: begin
            if (valid_in == 1'b1) begin
                data_out_next = data_in;
                state_next = RUN;
                count_next = 2'b01;
            end
            else begin
                data_out_next = data_out;
                state_next = WAIT;
                count_next = count;
            end
        end
        RUN: begin
            if (count == 2'b11) begin
                data_out_next = data_in + data_out;
                state_next = WAIT_OUT;
                count_next = count;
            end
            else begin
                data_out_next = data_out;
                state_next = state;
                count_next = count + 1'b1;
            end
        end
        WAIT_OUT: begin
            data_out_next = data_out;
            state_next = WAIT;
            count_next = 2'b00;
        end
        default: begin
            data_out_next = data_out;
            state_next = state;
            count_next = count;
        end
    endcase
end
always @(posedge clk or negedge rst_n)
begin
    if (~rst_n) begin
        state <= WAIT;
        count <= 2'b00;
        data_out <= 10'b0;
    end
    else begin
        state <= state_next;
        count <= count_next;
        data_out <= data_out_next;
    end
end
always @*
begin
    if ((state == WAIT_OUT) && (count == 2'b11))
        valid_out = 1'b1;
    else
        valid_out = 1'b0;
end
endmodule

