module float_multi
(
	input  wire  clk,
	input  wire  rst,
	input  wire  en,
	input  wire [31:0] a,
	input  wire [31:0] b,
	output wire [31:0] z
);
reg [2:0] counter;
reg [23:0] a_mantissa, b_mantissa, z_mantissa;
reg [23:0] norm_a_mantissa, norm_b_mantissa, norm_z_mantissa;
reg [9:0] a_exponent, b_exponent, z_exponent;
reg a_sign, b_sign, z_sign;
reg [49:0] product;
reg guard_bit, round_bit, sticky;
reg z_nan_or_inf;

generate
	genvar i;
	for (i = 0;
 i < 24;
 i = i + 1) begin : Generate_Z_Result

		assign norm_a_mantissa[i] = a_mantissa[i] | counter > i;
		assign norm_b_mantissa[i] = b_mantissa[i] | counter > i;
		assign norm_z_mantissa[i] = product[(i * 2) + 1] | counter > i;
	end
	assign z = {z_sign, z_exponent[8:0], z_mantissa};
endgenerate
always @(posedge clk) begin
	if (rst) begin
		counter <= 0;
	end else if (en) begin
		case (counter)
			3'd0: begin
				a_mantissa <= a[22:0];
				b_mantissa <= b[22:0];
				a_exponent <= a[30:23];
				b_exponent <= b[30:23];
				a_sign <= a[31];
				b_sign <= b[31];
				counter <= counter + 1;
			end
			3'd1: begin
				a_mantissa <= {1'b1, a_mantissa[22:1]};
				b_mantissa <= {1'b1, b_mantissa[22:1]};
				a_exponent <= a_exponent - 1;
				b_exponent <= b_exponent - 1;
				counter <= counter + 1;
			end
			3'd2: begin
				if (a_exponent[9] | b_exponent[9]) begin

					z_sign <= 0;
					z_exponent <= 127;
					z_mantissa <= 127;
					z_nan_or_inf <= 1;
				end else begin
					guard_bit <= product[0];
					round_bit <= product[1];
					sticky <= product[2] | |product[19:2];
					if (a[22:0] == 'b0 | b[22:0] == 'b0) begin
						z_sign <= 0;
						z_exponent <= 0;
						z_mantissa <= 0;
						z_nan_or_inf <= 0;
					end else begin
						if (counter < 3'd5) begin
							counter <= counter + 1;
						end else if ($signed(a_exponent) + $signed(b_exponent) - 30 + 23 < 0) begin
							z_sign <= 0;
							z_exponent <= 0;
							z_mantissa <= 0;
							z_nan_or_inf <= 0;
						end else begin
							z_sign <= a_sign ^ b_sign;
							z_exponent <= a_exponent + b_exponent - 30 + 23;
							z_mantissa <= product[48:26];
							z_nan_or_inf <= 0;
						end
					end
				end
			end
			3'd5: begin
				if (z_nan_or_inf) begin
					if (guard_bit && ((round_bit & sticky) | round_bit)) begin
						z_exponent <= z_exponent + 1;
					end
				end else begin
					counter <= counter + 1;
				end
			end
			3'd6: begin
				if (z_nan_or_inf) begin
					if (guard_bit && ((round_bit & sticky) | round_bit)) begin
						z_mantissa <= z_mantissa + 1;
					end
				end else begin
					counter <= counter + 1;
				end
			end
			3'd7: begin
				counter <= counter + 1;
			end
			3'd8: begin
				counter <= 0;
			end
		endcase
	end
end
always @* begin
	product = ($signed(norm_a_mantissa) * $signed(norm_b_mantissa));
end
