    RW, 
    EN, 
    Rst, 
    Clk, 
    EMPTY, 
    FULL, 
    dataOut
) ;
input [3:0] dataIn ;
input RW, EN, Rst, Clk ;
output reg [3:0] dataOut ;
output EMPTY, FULL ;
reg [3:0] stack_mem [3:0] ;
reg [2:0] SP ;
