    if(EN) begin
        if(Rst) begin
            for (i = 0 ;
 i < 4 ;
 i = i + 1) begin
                stack_mem[i] <= 0;
            end
            SP <= 4 ;
            EMPTY <= 1;
            FULL <= 0;
            dataOut <= 0;
        end
        else begin
            FULL <= (SP == 3) ? 1:0 ;
            EMPTY <= (SP == 4) ? 1:0 ;
            if(RW) begin
                if(!EMPTY) begin
                    SP <= SP + 1;
                    dataOut <= stack_mem[SP-1] ;
                    stack_mem[SP-1] <= 0;
                end
            end
            else begin
                if(!FULL) begin
                    SP <= SP - 1;
                    stack_mem[SP-1] <= dataIn;
                end
            end
        end
    end
end
