module pulse_detect(clk, rst_n, data_in, data_out) ;
    input clk, rst_n ;
    input data_in ;
    output data_out ;
    reg data_out ;
    reg[2:0] state ;
    reg[2:0] nxt_state ;
    reg[1:0] first_half, sec_half ;
    localparam ZERO = 3'b000;
    localparam ONE = 3'b001 ;
    localparam ZERO2ONE = 3'b010 ;
    localparam ONE2ZERO = 3'b100 ;
    localparam ZERO2ONE2ZERO = 3'b011 ;
    always @ ( posedge clk, negedge rst_n )
       if(~rst_n) begin
            state <= ZERO ;
           data_out <=0;
        end
        else
            state <= nxt_state ;
    always @ (state, data_in) begin
       nxt_state = state ;
       case(state)
         ZERO : if( data_in ) 
                    nxt_state = ONE2ZERO ;
                else 
                    nxt_state = ZERO ;
         ONE : if( data_in ) 
                    nxt_state = ONE2ZERO ;
               else 
                    nxt_state = ZERO2ONE2ZERO ;
         ZERO2ONE2ZERO : if( data_in ) 
                    nxt_state = ZERO2ONE ;
                    else 
                    nxt_state = ZERO2ONE2ZERO ;
         ONE2ZERO : if( data_in ) 
                    nxt_state = ONE ;
                   else 
                    nxt_state = ZERO2ONE ;
         ZERO2ONE: if( data_in ) 
                    nxt_state = ZERO2ONE2ZERO ;
                   else 
                    nxt_state = ZERO2ONE ;

       endcase
    end
    always @ ( posedge clk )
       if(~rst_n) begin
            sec_half <=0;
        end
