module traffic_light(rst_n, clk, pass_request, clock, red, yellow, green);
    input rst_n, clk, pass_request;
    output reg [7:0] clock;
    output reg red, yellow, green;
    reg [1:0] state;
    parameter idle=2'b00, s1_red=2'b01, s2_yellow=2'b10, s3_green=2'b11;
    reg [7:0] cnt;
    reg p_red, p_yellow, p_green;
    always @(posedge clk, negedge rst_n)begin
        if(!rst_n)
            state <= idle;
        else begin
            case(state)
                idle:
                    state <= s1_red;
                s1_red:
                    if(cnt>3)
                        state <= s3_green;
                    else 
                        state <= s1_red;
                s2_yellow:
                    if(cnt>3)
                        state <= s1_red;
                    else
                        state <= s2_yellow;
                s3_green:
                    if(cnt>3)
                        state <= s2_yellow;
                    else
                        state <= s3_green;
                default:
                    state <= idle;
            endcase
        end
    end
    always @(posedge clk, negedge rst_n)begin
        if(!rst_n)
            cnt <= 10;
        else if(pass_request && green)begin
                if(cnt > 10)
                    cnt <= 10;
                else 
                    cnt <= cnt;
        end 
        else if(!green && p_green)
                cnt <= 60;
        else if(!yellow && p_yellow)
                cnt <= 5;
        else if(!red && p_red)
                cnt <= 10;
        else
            cnt <= cnt - 1;
    end
    assign clock = cnt;
    always @(posedge clk, negedge rst_n)begin
        if(!rst_n)
            {red, yellow, green} <= 3'b0;
        else begin
            red <= p_red;
            yellow <= p_yellow;
            green <= p_green;
        end
    end
    always @(state)begin
        {p_red, p_yellow, p_green} <= 3'b0;
        case(state)
            idle:
                {p_red, p_yellow, p_green} <= 3'b0;
            s1_red:
                p_red <= 1;
            s2_yellow:
                p_yellow <= 1;
            s3_green:
                p_green <= 1;
            default:
                {p_red, p_yellow, p_green} <= 3'b0;
        endcase
    end
endmodule

