    input [7:0]  B;
    output [15:0] result;
    output [15:0] odd;
    reg [15:0] result;
    reg [15:0] odd;
    reg [15:0] a_reg;
    reg [7:0] b_reg;
    always @ (A, B) begin
        a_reg = A;
        b_reg = B;
    end
    always @ (a_reg, b_reg) begin
        result = 0;
        odd = a_reg;
        while (odd >= b_reg) begin
            result = (result << 1) + 1;
            odd = odd - b_reg;
            if (~|odd && odd < b_reg) begin
                result = result - 1;
                odd = odd + b_reg;
            end
        end
        result = (result << 1) + odd;
    end
