module accu(
	clk,
	rst_n,
	data_in,
	valid_in,
	valid_out,
	data_out
) ;
input				clk, rst_n;
input		[7:0]	data_in;
input				valid_in;
output				valid_out;
output	[9:0]	data_out;
reg		[9:0]	data_out;
reg				valid_out;
reg		[2:0]	valid_stage;
reg		[7:0]	data_in1, data_in2, data_in3, data_in4;
reg		[7:0]	add_output;
reg		[2:0]	i;

always @(posedge clk or negedge rst_n) begin
	if (!rst_n) begin
		valid_stage <= 0;
		valid_out   <= 0;
		i           <= 0;
	end
	else begin
		valid_out <= 0;
		if (valid_in) begin
			if (valid_stage < 3'd4) begin
				valid_stage <= valid_stage + 1'b1;
				i           <= i + 1'b1;
			end
			else begin
				valid_stage <= 1'b0;
				i           <= 1'b0;
				valid_out   <= 1'b1;
			end
		end
	end
end

always @(posedge clk or negedge rst_n) begin
	if (!rst_n) begin
		data_in1   <= 0;
		data_in2   <= 0;
		data_in3   <= 0;
		data_in4   <= 0;
		add_output <= 0;
	end
	else begin
		if (valid_in) begin
			case (i)
				0: data_in1   <= data_in;
				1: data_in2   <= data_in;
				2: data_in3   <= data_in;
				3: data_in4   <= data_in;
				default:;
			endcase
		end
		if (valid_in && (i==3'd3)) begin
			add_output <= data_in1+data_in2+data_in3+data_in4;
		end
	end
end

always @(posedge clk or negedge rst_n) begin
	if (!rst_n) begin
		data_out <= 0;
	end
	else begin
		if (valid_out) begin
			data_out <= {add_output, 1'b1};
		end
		else begin
			data_out <= 0;
		end
	end
end
endmodule

