module fsm(IN, CLK, RST, MATCH) ;
	input IN, CLK, RST;
	output MATCH;
	reg MATCH;
	integer loop_count;
	parameter TIMEOUT = 5;
	reg [1:0] state;
	always @(IN or posedge CLK or posedge RST) begin
		if(RST) begin
			MATCH <= 1'b0;
		end else if (state == 2'b00 || state == 2'b01) begin
			MATCH <= 1'b0;
		end else if (state == 2'b10) begin
			MATCH <= IN;
		end
	end
	always @ (posedge CLK) begin
		if (RST) begin
			state <= 2'b00;
		end else begin
			case (state)
				2'b00: begin
					if (IN == 1'b1) begin
						state <= 2'b01;
					end else begin
						state <= 2'b00;
					end
				end
				2'b01: begin
					if (IN == 1'b1) begin
						state <= 2'b00;
					end else begin
						state <= 2'b10;
					end
				end
				2'b10: begin
					if (IN == 1'b1) begin
						state <= 2'b01;
					end else begin
						state <= 2'b11;
					end
				end
				2'b11: begin
					if (IN == 1'b1) begin
						state <= 2'b00;
					end else begin
						state <= 2'b01;
					end
				end
			endcase
		end
	end
endmodule

