module sequence_detector(clk, reset_n, data_in, sequence_detected) ;
    input clk, reset_n, data_in;
    output sequence_detected;
    reg sequence_detected;
    reg [2:0] present_state, next_state;
    parameter IDLE = 3'b000, S1 = 3'b001, S2 = 3'b010, S3 = 3'b011, S4 = 3'b100;
    always @(posedge clk or negedge reset_n) begin
        if (~reset_n)
            present_state <= IDLE;
        else 
            present_state <= next_state;
    end
    always @(*) begin
        sequence_detected = 1'b0;
        case (present_state)
            IDLE: next_state = data_in ? IDLE : S1;
            S1: next_state = data_in ? S2 : S1;
            S2: next_state = data_in ? S3 : S1;
            S3: next_state = data_in ? S4 : S1;
            S4: begin
                next_state = data_in ? S2 : S1;
                sequence_detected = 1'b1;
            end
        endcase
    end
endmodule

