			dataOut <= 4'h0;
			{stack_mem[0], stack_mem[1], stack_mem[2], stack_mem[3]} <= 16'h0000;
		end
		else begin
			if (~FULL)
				FULL <= (SP==0) ? 1'b1 : 1'b0 ;
			else if (RW)
				{stack_mem[SP],dataOut,SP} <= {4'h0, stack_mem[SP+1],SP+1} ;
			else if (~RW) begin
				{stack_mem[SP],SP} <= {dataIn,SP-1} ;
				EMPTY <= (SP==4) ? 1'b1 : 1'b0 ;
			end
		end
	end
end
