            data_out <= 0 ;
            state[4] <= 0 ;
            state[3] <= 0 ;
            state[2] <= 0 ;
            state[1] <= 0 ;
            state[0] <= 0 ;
        end else begin
            case (state)
                5'b00001 : begin
                    if (data_in == 1) state <= 5'b00010 ;
