                    if (data_in == 0) state <= 5'b01000 ;
                end
                5'b01000 : begin
                    if (data_in == 0) state <= 5'b10000 ;
                    else state <= 5'b00001 ;
                end
                5'b10000 : begin
                    if (data_in == 0) state <= 5'b00001 ;
                end
            endcase
        end
        data_out = state[2] & ~state[1] & ~state[0] ;
    end
