module alu (
    a, b, aluc, 
    r, zero, carry, negative, overflow, flag
) ;
    input [31:0] a, b ;

    input [5:0] aluc ;

    output [31:0] r ;

    output zero, carry, negative, overflow, flag ;


    wire [32:0] sra, srl, sll ;

    wire [32:0] srau, srlv, sllv ;
    wire [31:0] r ;

    wire zero, carry, negative, overflow, flag ;

    parameter ADD = 6'b100000 ;
    parameter ADDU = 6'b100001 ;
    parameter SUB = 6'b100010 ;
    parameter SUBU = 6'b100011 ;
    parameter AND = 6'b100100 ;
    parameter OR = 6'b100101 ;
    parameter XOR = 6'b100110 ;
    parameter NOR = 6'b100111 ;
    parameter SLT = 6'b101010 ;
    parameter SLTU = 6'b101011 ;
    parameter SLL = 6'b000000 ;
    parameter SRL = 6'b000010 ;
    parameter SRA = 6'b000011 ;
    parameter SLLV = 6'b000100 ;
    parameter SRLV = 6'b000110 ;
    parameter SRAV = 6'b000111 ;
    parameter LUI = 6'b001111 ;
    wire signed [31:0] sa, sb ;

    assign sa = a ;

    assign sb = b ;
    reg [32:0] res ;

    assign r = res[31:0] ;
    assign zero = (res==33'b0) ? 1'b1 : 1'b0 ;

    assign carry = res[32] ;

    assign negative = res[31] ;

    assign overflow = (aluc == SUB || aluc == SUBU) ? (a[31] ^ b[31] ^ sa[31] ^ res[31]) :
                        (a[31] ^ sb[31] ^ sa[31] ^ res[31]) ;

    assign flag = (aluc == SLT || aluc == SLTU) ? res[0] : 1'bz ;

    assign sra = (sa >>> sb[4:0]) ;

    assign srau = (sa >>> a[4:0]) ;

    assign srl = (sa >> sb[4:0]) ;

    assign srlv = (sa >> a[4:0]) ;

    assign sll = (sa << sb[4:0]) ;

    assign sllv = (sa << a[4:0]) ;

    assign rui = {a[15:0], 16'b0} ;


    always @(a or b or aluc)
    begin
        if (aluc == ADD)
            res = sa + sb ;
        else if (aluc == ADDU)
            res = a + b ;
        else if (aluc == SUB)
            res = sa - sb ;
        else if (aluc == SUBU)
            res = a - b ;
        else if (aluc == AND)
            res = a & b ;
        else if (aluc == OR)
            res = a | b ;
        else if (aluc == XOR)
            res = a ^ b ;
        else if (aluc == NOR)
            res = ~(a | b) ;
        else if (aluc == SLT)
            res = (sa < sb) ? 33'b1 : 33'b0 ;
        else if (aluc == SLTU)
            res = (a < b) ? 33'b1 : 33'b0 ;
        else if (aluc == SLL)
            res = sll ;
        else if (aluc == SRL)
            res = srl ;
        else if (aluc == SRA)
            res = sra ;
        else if (aluc == SLLV)
            res = sllv ;
        else if (aluc == SRLV)
            res = srlv ;
        else if (aluc == SRAV)
            res = srau ;
        else if (aluc == LUI)
            res = rui ;
        else
            res = 33'bz ;

    end
endmodule

