module sequence_detector(clk, reset_n, data_in, sequence_detected) ;
    input clk, reset_n, data_in ;
    output sequence_detected ;
    reg [1:0] present_state, next_state ;

    parameter [1:0] IDLE = 2'd0,
                    S1   = 2'd1,
                    S2   = 2'd2,
                    S3   = 2'd3,
                    S4   = 2'd4 ;

    always @ (present_state or data_in)
        case (present_state)
            IDLE: if (data_in) next_state = S1 ;
                  else        next_state = IDLE ;
            S1:   if (data_in) next_state = S2 ;
                  else        next_state = IDLE ;
            S2:   if (data_in) next_state = S3 ;
                  else        next_state = IDLE ;
            S3:   if (data_in) next_state = S4 ;
                  else        next_state = IDLE ;
            S4:   if (data_in) next_state = S1 ;
                  else        next_state = IDLE ;
            default: next_state = IDLE ;
        endcase

    always @ (posedge clk or negedge reset_n)
        if (~reset_n) present_state <= IDLE ;
        else present_state <= next_state ;

    assign sequence_detected = (present_state == S4) ;
endmodule

