module LIFObuffer(dataIn,RW,EN,Rst,Clk,EMPTY,FULL,dataOut) ;

input [3:0] dataIn ;

input RW,EN,Rst,Clk ;
output EMPTY, FULL ;
output [3:0] dataOut ;
reg [3:0] stack_mem[3:0] ;

reg [2:0] SP ;

wire EMPTY, FULL ;
reg [3:0] dataOut ;
assign EMPTY = (SP==3'd4)? 1'b1 : 1'b0 ;
assign FULL = (SP==3'd0)? 1'b1 : 1'b0 ;
always @ (posedge Clk) begin
	if (EN) begin 
		if(Rst) begin
			SP <= 3'd4 ;

			stack_mem[0] <= 4'd0 ;
			stack_mem[1] <= 4'd0 ;
			stack_mem[2] <= 4'd0 ;
			stack_mem[3] <= 4'd0 ;
			dataOut <= 4'd0 ;
		end
		else begin 
			if (FULL && RW) begin
				dataOut <= stack_mem[SP] ;

				stack_mem[SP] <= 4'd0 ;

				SP <= SP+1 ;

			end
			else if (!FULL && !RW) begin
				SP <= SP-1 ;

				stack_mem[SP] <= dataIn ;

			end
		end
	end
end
endmodule

