module pulse_detect(clk, rst_n, data_in, data_out) ;
    input clk, rst_n, data_in ;
    output data_out ;
    reg data_out ;
    reg [3:0] state ;
    always @ ( posedge clk or negedge rst_n ) begin
        if (~rst_n) begin
            state <= 4'b0000 ;
            data_out <= 1'b0 ;
            end
        else case ( state )
            4'b0000 : state <= data_in ? 4'b0001 : 4'b0000 ;
            4'b0001 : state <= data_in ? 4'b0011 : 4'b0010 ;
            4'b0010 : state <= data_in ? 4'b0001 : 4'b0000 ;
            4'b0011 : state <= data_in ? 4'b0100 : 4'b0010 ;
            4'b0100 : state <= data_in ? 4'b0110 : 4'b0101 ;
            4'b0101 : state <= data_in ? 4'b0011 : 4'b0010 ;
            4'b0110 : state <= data_in ? 4'b1000 : 4'b0101 ;
            4'b1000 : state <= data_in ? 4'b1010 : 4'b1001 ;
            4'b1001 : state <= data_in ? 4'b0100 : 4'b0010 ;
            4'b1010 : state <= data_in ? 4'b1100 : 4'b1001 ;
            4'b1100 : state <= data_in ? 4'b0111 : 4'b1011 ;
            4'b1111 : state <= data_in ? 4'b0001 : 4'b0000 ;
            default: state <= 4'b0000 ;
        endcase
    end
    always @ ( posedge clk or negedge rst_n ) begin
        if (~rst_n) data_out <= 1'b0 ;
        else if ( state[3] ) data_out <= 1'b1 ;
        else data_out <= 1'b0 ;
    end
