  reg          start_cnt;
  reg [ 7:0]   DIVIDEND;
  reg [ 7:0]   DIVISOR;
  reg [16:0]   SR;

  reg [ 8:0]   NEG_DIVISOR;

  reg [ 8:0]   C ;

  reg [ 8:0]   SUB_OUT ;

