  reg [ 8:0]   opn;

  reg [ 3:0]   cnt;


  reg        S ;

  reg        opn_vld;
  reg [15:0] SR_out ;
  always @(posedge clk) begin
    if(rst==1'b1) begin
      opn <= 0;
      opn_vld <= 0;
    end else if (opn_valid == 1'b1 && res_valid == 1'b0) begin
      opn <= {dividend[7:0],1'b1,divisor[7:0]};
