module float_multi (
    clk,
    rst,
    a,
    b,
    z
) ;

input clk;
input rst;
input [31:0] a;
input [31:0] b;
output reg [31:0] z;

reg [49:0] product;

reg [2:0] counter;
reg [23:0] a_mantissa, b_mantissa, z_mantissa;
reg [9:0] a_exponent, b_exponent, z_exponent;
reg a_sign, b_sign, z_sign;
reg guard_bit, round_bit, sticky;
always @(posedge clk or posedge rst) begin : FLOAT_MULTI
    reg [49:0] prod_local;

    if (rst)
    begin
        counter <= 3'b0;
    end
    else
    begin
        case (counter)
            3'b000:
            begin

                a_mantissa <= { 1'b1 , a[22:0] };
                a_exponent <= a[30:23];
                a_sign <= a[31];

                b_mantissa <= { 1'b1 , b[22:0] };
                b_exponent <= b[30:23];
                b_sign <= b[31];
                counter <= counter + 1;
            end
            3'b001:
            begin

                z_exponent <= 10'b0;
                z_mantissa <= 24'b0;
                z_sign <= 1'b0;
                if (a[30:23] == 8'b11111111) begin
                    z_exponent <= 10'b1111111111;
                    z_mantissa <= 24'b0;
                    z_sign <= 1'b1;
                end
                else if (b[30:23] == 8'b11111111) begin
                    z_exponent <= 10'b1111111111;
                    z_mantissa <= 24'b0;
                    z_sign <= a_sign ^ b_sign;
                end
                else begin
                    counter <= counter + 1;
                end
            end
            3'b010:
            begin

                if (a_exponent == 0) begin
                    a_exponent <= 10'b0;
                    a_mantissa <= 25'b0;
                end
                if (b_exponent == 0) begin
                    b_exponent <= 10'b0;
                    b_mantissa <= 25'b0;
                end
                counter <= counter + 1;
            end
            3'b011:
            begin

                if (a_exponent != 0)
                    a_exponent <= a_exponent - 10'b0111111111;
                if (b_exponent != 0)
                    b_exponent <= b_exponent - 10'b0111111111;
                counter <= counter + 1;
            end
            3'b100:
            begin

                if (a_mantissa[23] == 0) begin
                    a_mantissa <= a_mantissa << 1;
                    a_exponent <= a_exponent + 1'b1;
                end
                if (b_mantissa[23] == 0) begin
                    b_mantissa <= b_mantissa << 1;
                    b_exponent <= b_exponent + 1'b1;
                end
                counter <= counter + 1;
            end
            3'b101:
            begin

                prod_local <= a_mantissa * b_mantissa;
                guard_bit <= prod_local[23];
                round_bit <= prod_local[22];
                sticky <= (prod_local[22:0] != 24'b0);
                z_exponent <= a_exponent + b_exponent - 10'b0111111111 + 10'b0000000001;
                z_sign <= a_sign ^ b_sign;
                counter <= counter + 1;
            end
            3'b110:
            begin

                z_mantissa <= prod_local[49:25];
                if (guard_bit) begin
                    if (round_bit || sticky) begin
                        z_mantissa <= z_mantissa + 25'b000000000000000000000000001;
                        if (z_mantissa == 24'b111111111111111111111111) begin
                            z_mantissa <= 24'b0;
                            z_exponent <= z_exponent + 10'b0000000001;
                        end
                    end
                end
                else if (round_bit) begin
                    z_mantissa <= z_mantissa + 25'b000000000000000000000000001;
                    if (z_mantissa == 24'b111111111111111111111111) begin
                        z_mantissa <= 24'b0;
                        z_exponent <= z_exponent + 10'b0000000001;
                    end
                end
                else if (sticky) begin
                    z_mantissa <= z_mantissa + 25'b000000000000000000000000001;
                    if (z_mantissa == 24'b111111111111111111111111) begin
                        z_mantissa <= 24'b0;
                        z_exponent <= z_exponent + 10'b0000000001;
                    end
                end

                if (z_exponent[9]) begin
                    z_exponent <= 10'b1111111111;
                    z_mantissa <= 24'b0;
                    z_sign <= 1'b1;
                end
                else if (z_exponent == 0) begin
                    z_exponent <= 10'b0;
                    z_sign <= a_sign ^ b_sign;
                    z_mantissa <= { 1'b0, z_mantissa[22:0] };
                end
                counter <= counter + 1;
            end
            3'b111:
            begin

                if (a[30:23] == 8'b11111111) begin
                    z_exponent <= 10'b1111111111;
                    z_mantissa <= 24'b0;
                    z_sign <= 1'b1;
                end
                else if (b[30:23] == 8'b11111111) begin
                    z_exponent <= 10'b1111111111;
                    z_mantissa <= 24'b0;
                    z_sign <= a_sign ^ b_sign;
                end
                else begin
                    z[31] <= z_sign;
                    z[30:23] <= z_exponent[8:1];
                    z[22:0] <= z_mantissa[22:0];
                end
                counter <= 3'b000;
            end
        endcase
    end
end
endmodule

