module sub_64bit(
		A, B, result, overflow
		);
parameter DATA_WIDTH = 64;
input [DATA_WIDTH - 1:0] A, B;
output [DATA_WIDTH - 1:0] result;
output overflow;
wire [DATA_WIDTH - 1:0] A, B, result;
wire overflow;
wire [64:0] temp;
assign temp = {1'b0, A} - {1'b0, B};
assign result = temp[DATA_WIDTH - 1:0];
assign overflow = (A[DATA_WIDTH - 1] & ~B[DATA_WIDTH - 1] & ~temp[DATA_WIDTH - 1]) | (~A[DATA_WIDTH - 1] & B[DATA_WIDTH - 1] & temp[DATA_WIDTH - 1]);
endmodule

