module fsm(
    input CLK, RST, IN,
    output reg MATCH
);

    localparam WAIT1 = 3'b000;
    localparam STATE1 = 3'b001;
    localparam STATE2 = 3'b010;
    localparam STATE3 = 3'b011;
    localparam STATE4 = 3'b100;
    localparam DONE = 3'b101;
    reg [2:0] state, next_state;

    always @(posedge CLK or posedge RST) begin
        if (RST)
            state <= WAIT1;
        else
            state <= next_state;
    end

    always @(*) begin
        case (state)
            WAIT1: begin
                next_state = IN ? STATE1 : WAIT1;
                MATCH = 1'b0;
            end
            STATE1: begin
                next_state = IN ? STATE1 : STATE2;
                MATCH = 1'b0;
            end
            STATE2: begin
                next_state = IN ? STATE3 : WAIT1;
                MATCH = 1'b0;
            end
            STATE3: begin
                next_state = IN ? STATE4 : STATE2;
                MATCH = 1'b0;
            end
            STATE4: begin
                next_state = IN ? DONE : WAIT1;
                MATCH = 1'b1;
            end
            DONE: begin
                next_state = IN ? STATE1 : WAIT1;
                MATCH = 1'b0;
            end
            default: next_state = WAIT1;
        endcase
    end
endmodule

