begin
    if(reset_n == 0)
        current_state <= IDLE;
    else
        current_state <= next_state;
end
always@(data_in, current_state)
begin
    case (current_state)
        IDLE:
        begin
            if (data_in == 1)
                next_state <= S1;
            else
                next_state <= IDLE;
        end
        S1:
        begin
            if (data_in == 0)
                next_state <= S2;
            else
                next_state <= S1;
        end
        S2:
