            if (data_in == 1)
                next_state <= S4;
            else
                next_state <= S2;
        end
        S4:
        begin
            if (data_in == 0)
                next_state <= S1;
            else
                next_state <= S3;
        end
        default: next_state <= IDLE;
    endcase
end
always@(current_state)
begin
    if (current_state == S4)
        sequence_detected <= 1'b1;
    else
        sequence_detected <= 1'b0;
end
