module alu
    (
        a
        ,b
        ,aluc
        ,r
        ,zero
        ,carry
        ,negative
        ,overflow
        ,flag
    );
    input wire [31:0] a;
    input wire [31:0] b;
    input wire [5:0] aluc;
    output wire [31:0] r;
    output wire zero;
    output wire carry;
    output wire negative;
    output wire overflow;
    output wire flag;

    parameter ADD = 6'b100000;
    parameter ADDU = 6'b100001;
    parameter SUB = 6'b100010;
    parameter SUBU = 6'b100011;
    parameter AND = 6'b100100;
    parameter OR = 6'b100101;
    parameter XOR = 6'b100110;
    parameter NOR = 6'b100111;
    parameter SLT = 6'b101010;
    parameter SLTU = 6'b101011;
    parameter SLL = 6'b000000;
    parameter SRL = 6'b000010;
    parameter SRA = 6'b000011;
    parameter SLLV = 6'b000100;
    parameter SRLV = 6'b000110;
    parameter SRAV = 6'b000111;
    parameter LUI = 6'b001111;
    wire signed [31:0] aa;
    wire signed [31:0] bb;
    wire signed [31:0] res;
    assign aa = a;
    assign bb = b;
    assign r = res[31:0];
    reg [32:0] res;

    always @(*)
    begin
        case (aluc)
            ADD:     res = a + b;
            ADDU:    res = {1'b0, a} + {1'b0, b};
            SUB:     res = a - b;
            SUBU:    res = {1'b0, a} - {1'b0, b};
            AND:     res = a & b;
            OR:      res = a | b;
            XOR:     res = a ^ b;
            NOR:     res = ~(a | b);
            SLT:     res = {1'b0, (aa < bb)};
            SLTU:    res = {1'b0, (a < b)};
            SLL:     res = b << a[4:0];
            SRL:     res = b >> a[4:0];
            SRA:     res = b >>> a[4:0];
            SLLV:    res = b << a[4:0];
            SRLV:    res = b >> a[4:0];
            SRAV:    res = b >>> a[4:0];
            LUI:     res = {a[15:0], 16'h0};
            default: res = 33'hz;
        endcase
    end

    assign flag = (aluc == SLT || aluc == SLTU)?res[0]:1'bz;
    assign zero = res == 32'h0;
    assign carry = res[32];
    assign negative = res[31];
    assign overflow = aluc == ADD && a[31] == b[31] && a[31] != res[31] ||
                    aluc == SUB && a[31] != b[31] && a[31] != res[31];
endmodule

