module radix2_div (
    input wire clk,
    input wire rst,
    input wire sign,
    input wire [7:0] dividend,
    input wire [7:0] divisor,
    input wire opn_valid,
    output wire res_valid,
    output reg [15:0] result
) ;
    reg [7:0] dividend_reg;
    reg [7:0] divisor_reg;
    reg [15:0] SR;
    reg [7:0] NEG_DIVISOR;
    wire [8:0] sub;
    wire carry;
    reg start_cnt;
    reg [4:0] cnt;
    reg res_valid_reg;
    reg result_consumed;
    assign opn_valid_pulse = opn_valid & (~result_consumed);
    assign dividend_pulse = opn_valid_pulse & (~sign);
    assign divisor_pulse = opn_valid_pulse & sign;
    always @(posedge clk or posedge rst) begin
        if (rst == 1) begin
            res_valid_reg <= 0;
            result_consumed <= 0;
        end
        else if ((cnt == 4'b1000) & (res_valid_reg == 0) & (result_consumed == 0))
            res_valid_reg <= 1;
        else if (result_consumed)
            res_valid_reg <= 0;
    end
    always @(posedge clk) begin
        if (opn_valid_pulse == 1)
            result_consumed <= 0;
        else
            result_consumed <= res_valid;
    end
    always @(posedge clk or posedge rst) begin
        if (rst == 1)
            start_cnt <= 0;
        else if (opn_valid_pulse == 1)
            start_cnt <= 1;
        else if ((cnt == 4'b1000) & (res_valid_reg == 0))
            start_cnt <= 0;
    end
    always @(posedge clk) begin
        if (dividend_pulse == 1)
            dividend_reg <= dividend;
        else if (divisor_pulse == 1)
            divisor_reg <= divisor;
        else
            divisor_reg <= divisor_reg;
    end
    always @(posedge clk) begin
        if (opn_valid_pulse == 1)
            NEG_DIVISOR <= (~divisor_reg)+1;
        else
            NEG_DIVISOR <= NEG_DIVISOR;
    end
    always @(posedge clk or posedge rst) begin
        if (rst == 1)
            SR <= {8'b0, dividend_reg};
        else if (opn_valid_pulse == 1)
            SR <= {8'b0, dividend_reg};
        else if (start_cnt == 1) begin
            if (sub[8] == 1)
                SR <= {SR[14:0], carry};
            else
                SR <= {SR[14:0], sub[8]};
        end
    end
    always @(posedge clk) begin
        if (opn_valid_pulse == 1)
            result <= 16'b0;
        else if (res_valid_reg == 1) begin
            if (sign == 0)
                result <= {8'b0,SR[14:8]};
            else if (sign == 1)
                result <= {SR[14:8], SR[7:0]};
        end
    end
    always @(posedge clk or posedge rst) begin
        if (rst == 1)
            cnt <= 5'b00001;
        else if (start_cnt == 1)
            cnt <= cnt+1;
        else
            cnt <= cnt;
    end
    assign sub = SR[15:7] + NEG_DIVISOR;
    assign carry = sub[8];
endmodule

