module comparator_4bit (
    input wire [3:0] A,
    input wire [3:0] B,
    output wire A_greater,
    output wire A_equal,
    output wire A_less
) ;
    wire [3:0] sub_result;
    wire carry;

    assign carry = (~A[3]) & B[3] | (~A[2]) & B[2] & B[3] | (~A[1]) & B[1] & B[2] & B[3] | (~A[0]) & B[0] & B[1] & B[2] & B[3];

    assign sub_result[0] = A[0] ^ B[0] ^ 1'b0;
    assign sub_result[1] = A[1] ^ B[1] ^ carry;
    assign sub_result[2] = A[2] ^ B[2] ^ carry;
    assign sub_result[3] = A[3] ^ B[3] ^ carry;

    assign A_greater = carry;
    assign A_equal = ~(sub_result[0] | sub_result[1] | sub_result[2] | sub_result[3]);
    assign A_less = ~(A_greater | A_equal);
endmodule

