module multi_16bit(
    clk, rst_n, start,
    ain, bin,
    yout, done
    ) ;
    parameter width = 16 ;
    input clk, rst_n, start ;
    input [width-1:0] ain, bin ;
    output done ;
    output [2*width-1:0] yout ;

    reg [4:0] i ;
    always @ ( posedge clk or negedge rst_n )
        if( !rst_n )
            i <= 5'd0 ;
        else if( start )
            if( i < 5'd17 )
                i <= i + 5'd1 ;
            else
                i <= 5'd0 ;
        else
            i <= 5'd0 ;

    reg done_r ;
    always @ ( posedge clk or negedge rst_n )
        if( !rst_n )
            done_r <= 1'b0 ;
        else if( i == 5'd16 )
            done_r <= 1'b1 ;
        else if( i == 5'd17 )
            done_r <= 1'b0 ;
    assign done = done_r ;

    reg [width-1:0] areg, breg ;
    reg [2*width-1:0] yout_r ;
    always @ ( posedge clk or negedge rst_n )
