                    sequence_detected = 1'b1 ;
                    next_state = S4;
                end else begin
                    next_state = IDLE;
                end
            S4:
                if (data_in) begin
                    sequence_detected = 1'b1 ;
                    next_state = S1;
                end else begin
                    next_state = IDLE;
                end
            default: next_state = IDLE;
        endcase
    end
