module traffic_light(rst_n, clk, pass_request, clock, red, yellow, green);
    input rst_n, clk, pass_request;
    output reg [7:0] clock;
    output reg red, yellow, green;
    reg [7:0] cnt;
    reg [1:0] state;
    reg p_red, p_yellow, p_green;
    parameter idle = 2'b00, s1_red = 2'b01, s2_yellow = 2'b10, s3_green = 2'b11;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= idle;
        end
        else begin
            case(state)
                idle: 
                    state <= s1_red;
                s1_red:
                    if (cnt == 3)
                        state <= s3_green;
                    else
                        state <= s1_red;
                s2_yellow:
                    if (cnt == 3)
                        state <= s1_red;
                    else
                        state <= s2_yellow;
                s3_green:
                    if (cnt == 3)
                        state <= s2_yellow;
                    else
                        state <= s3_green;
            endcase
        end
    end
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            cnt <= 8'd60;
        else begin
            if (pass_request && green) begin
                if (cnt > 8'd10)
                    cnt <= 8'd10;
            end
            else begin
                if (!green && p_green)
                    cnt <= 8'd60;
                else if (!yellow && p_yellow)
                    cnt <= 8'd5;
                else if (!red && p_red)
                    cnt <= 8'd10;
                else
                    cnt <= cnt - 1;
            end
        end
    end
    assign clock = cnt;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            p_red <= 1'b0;
            p_yellow <= 1'b0;
            p_green <= 1'b0;
        end
        else begin
            p_red <= red;
            p_yellow <= yellow;
            p_green <= green;
        end
    end
    always @(posedge clk) begin
        red <= (state == s1_red);
        yellow <= (state == s2_yellow);
        green <= (state == s3_green);
    end
endmodule

