            if (cnt == 4'd8) begin
                dout_valid_r <= 1'b1;
            end
            else begin
                dout_valid_r <= 1'b0;
            end
        end
    end
    assign dout_valid   = dout_valid_r;
    assign dout_parallel = din_buff;
endmodule

