module alu (
	input [31:0] a,
	input [31:0] b,
	input [5:0] aluc,
	output reg [31:0] r,
	output zero,
	output reg carry,
	output reg negative,
	output reg overflow,
	output flag
	) ;
	parameter ADD = 6'b100000;
	parameter ADDU = 6'b100001;
	parameter SUB = 6'b100010;
	parameter SUBU = 6'b100011;
	parameter AND = 6'b100100;
	parameter OR = 6'b100101;
	parameter XOR = 6'b100110;
	parameter NOR = 6'b100111;
	parameter SLT = 6'b101010;
	parameter SLTU = 6'b101011;
	parameter SLL = 6'b000000;
	parameter SRL = 6'b000010;
	parameter SRA = 6'b000011;
	parameter SLLV = 6'b000100;
	parameter SRLV = 6'b000110;
	parameter SRAV = 6'b000111;
	parameter LUI = 6'b001111;
	reg [32:0] res;

	assign zero = (res[31:0]==32'b0);
	assign flag = ((aluc == 6'b101010) | (aluc == 6'b101011))? res[0] : 1'bz ;

	wire [31:0] shamt;
	assign shamt = a[4:0] ;
	reg [4:0] shamt_tmp;

	always @(*) begin
		res = 0;
		casez (aluc)
			ADD:	begin
				res = a + b ;

				carry = res[32];
				negative = res[31];
				overflow = (a[31]==b[31]&a[31]!=res[31])? 1: 0;
			end 
			ADDU: begin
				res = a + b;

				carry = 1'b0;
				negative = 1'b0;
				overflow = 1'b0;
			end
			SUB:	begin
				res = a - b ;

				carry = res[32];
				negative = res[31];
				overflow = (a[31]!=b[31]&a[31]!=res[31])? 1: 0;
			end
			SUBU: begin
				res = a - b;
				carry = 1'b0;
				negative = 1'b0;
				overflow = 1'b0;
			end
			AND:	res = a & b ;
			OR:		res = a | b ;
			XOR:	res = a ^ b ;
			NOR:	res = ~ (a | b );
			SLT:	res = ($signed(a)<$signed(b));
			SLTU:	res = (a < b);
			SLL: 	begin
				res = b << shamt ;
				shamt_tmp = a[4:0];

			end 
			SRL:	begin
				res = b >> shamt ;
				shamt_tmp = a[4:0];

			end
			SRA:  begin
				res = $signed(b) >>> shamt ;
				shamt_tmp = a[4:0];

			end
			SLLV: begin 
				res = b << a[4:0];
				shamt_tmp = a[4:0];

			end
			SRLV: begin
				res = b >> a[4:0];
				shamt_tmp = a[4:0];

			end
			SRAV:	begin
				res = $signed(b) >>> a[4:0];
				shamt_tmp = a[4:0];

			end
			LUI:	res = {a[31:16], 16'b0};
			default: res = 33'bz;
		endcase
		r = res[31:0];
	end
endmodule

