        case(current_state)
            IDLE: 
                if(data_in == 1)
                    next_state = S1;
                else
                    next_state = IDLE;
            S1: 
                if(data_in == 0)
                    next_state = S2;
                else
                    next_state = S1;
            S2: 
                if(data_in == 0)
                    next_state = S3;
                else
                    next_state = IDLE;
            S3: 
                if(data_in == 1)
                    next_state = S4;
                else
                    next_state = IDLE;
            S4: 
                if(data_in == 1)
                    next_state = S1;
                else
                    next_state = S2;
            default: next_state = IDLE;
        endcase
    end

    assign sequence_detected = (current_state == S4) ? 1'b1 : 1'b0;

    always @(posedge clk) begin
        if(!reset_n) 
            current_state <= IDLE;
        else
            current_state <= next_state;
    end
