module LIFObuffer(
    dataIn,
    RW,
    EN,
    Clk,
    Rst,
    EMPTY,
    FULL,
    dataOut
) ;
input [3:0] dataIn;
input RW,EN,Clk,Rst;
output EMPTY,FULL;
output reg [3:0] dataOut;
reg [3:0] stack_mem[0:3];
reg [2:0] SP;
integer i;

assign EMPTY = (SP == 3'b111);
assign FULL = (SP == 3'b000);
always @(posedge Clk) begin
    if(EN)
    begin
        if(Rst)
        begin
            SP <= 3'b111;
            dataOut <= 4'bxxxx;
            for(i=0;
i<4;
i=i+1)
                stack_mem[i] <= 4'b0000;
        end
        else
        begin
            if(~FULL && RW)
            begin
                SP <= SP - 1;
                stack_mem[SP] <= dataIn;
            end
            else if(~EMPTY && ~RW)
            begin
                dataOut <= stack_mem[SP];
                stack_mem[SP] <= 4'bxxxx;
                SP <= SP + 1;
            end
        end
    end
    else
    begin
        dataOut <= 4'bzzzz;
    end
end
endmodule

