                if (data_in) nxt_state <= S1 ;
                else nxt_state <= S3 ;
            end
            S3 : begin
                data_out <= 1 ;
                if (data_in) nxt_state <= S1 ;
                else nxt_state <= S2 ;
            end
            default : begin
                data_out <= 0 ;
                nxt_state <= S0 ;
            end
        endcase
    end
