module adder_pipe_64bit (clk, rst_n, i_en, adda, addb, result, o_en) ;
    input           clk;
    input           rst_n;
    input           i_en;
    input  [63:0]   adda;
    input  [63:0]   addb;
    output [64:0]   result;
    output          o_en;

    wire   [64:0]   s1_sum;
    reg    [63:0]   r1_adda, r2_adda, r3_adda, r4_adda;
    reg    [63:0]   r1_addb, r2_addb, r3_addb, r4_addb;
    reg             r1_i_en, r2_i_en, r3_i_en, r4_i_en;
    reg             r1_o_en, r2_o_en, r3_o_en, r4_o_en;
    reg    [64:0]   r1_sum, r2_sum, r3_sum, r4_sum;

    always@(posedge clk or negedge rst_n) begin
        if(rst_n == 1'b0) begin
            {r1_adda, r1_addb, r1_i_en} <= {64'b0, 64'b0, 1'b0};
        end
        else begin
            {r1_adda, r1_addb, r1_i_en} <= {adda, addb, i_en};
        end
    end

    always@(posedge clk or negedge rst_n) begin
        if(rst_n == 1'b0) begin
            {r1_o_en, r2_o_en, r3_o_en, r4_o_en} <= {4{1'b0}};
        end
        else begin
            {r1_o_en, r2_o_en, r3_o_en, r4_o_en} <= {r2_o_en, r3_o_en, r4_o_en, r3_i_en};
        end
    end

    assign s1_sum = r1_adda + r1_addb;

    always@(posedge clk or negedge rst_n) begin
        if(rst_n == 1'b0) begin
            {r1_sum, r2_sum, r3_sum, r4_sum} <= {65{1'b0}};
        end
        else begin
            {r1_sum, r2_sum, r3_sum, r4_sum} <= {r1_sum, r2_sum, r3_sum, r4_sum, s1_sum};
        end
    end
    assign result = r4_sum;
    assign o_en = r4_o_en;
endmodule

