module accu(
    clk, rst_n, data_in, valid_in, 
    valid_out, data_out
) ;
    input           clk, rst_n ;
    input   [7:0]   data_in ;
    input           valid_in ;
    output  reg     valid_out ;
    output  reg [9:0]  data_out ;
    reg     [7:0]   data_in_reg ;
    reg     [1:0]   cnt_flag ;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt_flag <= 0 ;
        end
        else if (valid_in) begin
            if (cnt_flag == 3) begin
                cnt_flag <= 0 ;
            end
            else begin
                cnt_flag <= cnt_flag + 1 ;
            end
        end
        else begin
            cnt_flag <= cnt_flag ;
        end
    end
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            data_in_reg <= 0 ;
        end
        else if (valid_in) begin
            if (cnt_flag == 0) begin
                data_in_reg <= data_in ;
            end
            else begin
                data_in_reg <= data_in_reg ;
            end
        end
        else begin
            data_in_reg <= data_in_reg ;
        end
    end
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            valid_out <= 0 ;
        end
        else if (cnt_flag == 3) begin
            valid_out <= 1 ;
        end
        else begin
            valid_out <= 0 ;
        end
    end
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            data_out <= 0 ;
        end
        else if (cnt_flag == 3) begin
            data_out <= data_in_reg + data_in ;
        end
        else begin
            data_out <= data_out ;
        end
    end
endmodule

