            current_state <= IDLE;
        else
            current_state <= next_state;
    end
    always @ (current_state or data_in)
    begin: NEXT_STATE_LOGIC
        case (current_state)
        IDLE: 
            if (data_in == 1)
                next_state = S1;
            else
                next_state = IDLE;
        S1: 
            if (data_in == 0)
                next_state = S2;
            else
                next_state = S1;
        S2:
