            else
                next_state = IDLE;
        S4:
            if (data_in == 1)
                next_state = S1;
            else
                next_state = S3;
        endcase
    end
    always @ (posedge clk or negedge reset_n)
    begin: OUTPUT_LOGIC
        if (!reset_n)
            sequence_detected <= 0;
        else
            if (current_state == S4)
                sequence_detected <= 1;
            else
                sequence_detected <= 0;
