module LIFObuffer(dataIn, RW, EN, Rst, Clk, EMPTY, FULL, dataOut) ;
  input [3:0] dataIn ;
  input RW ;
  input EN ;
  input Rst ;
  input Clk ;
  output EMPTY ;
  output FULL ;
  output [3:0] dataOut ;

  reg [3:0] stack_mem [0:3] ;

  reg [2:0] SP ;

  assign FULL = (SP == 3'b111) ? 1'b1 : 1'b0;
  assign EMPTY = (SP == 3'b000) ? 1'b1 : 1'b0;
  assign dataOut = stack_mem[SP] ;
  always @ (posedge Clk)
    begin
      if (EN == 1'b1)
        begin
          if (Rst == 1'b1) 
            begin
              SP = 3'b100;
              stack_mem[0] <= 0;
              stack_mem[1] <= 0;
              stack_mem[2] <= 0;
              stack_mem[3] <= 0;
            end 
          else 
            begin
              if (FULL == 1'b0 && RW == 1'b0)
                begin
                  SP = SP - 1'b1;
                  stack_mem[SP] <= dataIn;
                end 
              else if (EMPTY == 1'b0 && RW == 1'b1) 
                begin
                  stack_mem[SP] <= 4'b0000;
                  SP = SP + 1'b1;
                end 
            end
        end 
    end
endmodule

