module traffic_light(rst_n, clk, pass_request, red, yellow, green, clock);

parameter cnt_size = 8, state_size = 2;
parameter idle = 2'b00, s1_red = 2'b01, s2_yellow = 2'b10, s3_green = 2'b11;
