output reg[cnt_size - 1: 0] clock;
output reg red, yellow, green;
reg[state_size - 1 : 0] state;
reg p_red, p_yellow, p_green;
reg[cnt_size - 1: 0] cnt, p_cnt;


always @(posedge clk or negedge rst_n)
begin
    if(!rst_n) state <= idle;

    else begin 
        case(state)
            idle : state <= s1_red;
            s1_red : if(cnt > 3'd2) state <= s3_green;

            s2_yellow : if(cnt > 3'd2) state <= s1_red;
            s3_green : if(cnt > 3'd2) state <= s2_yellow;
            default : state <= idle;
        endcase
    end
end

always @(posedge clk or negedge rst_n)
begin
    if(!rst_n) begin
        cnt <= 10;
    end else begin
        if(pass_request && green) begin
            if(cnt > 4'd10) cnt <= 10;

            else cnt <= 10;
        end else begin
            if(!green && p_green) begin
                if(cnt > 6'd59) cnt <= 60;

                else cnt <= 60;
            end else begin
                if(!yellow && p_yellow) begin
                    if(cnt > 4'd4) cnt <= 5;
                    else cnt <= 5;
                end else begin
                    if(!red && p_red) begin
                        if(cnt > 4'd9) cnt <= 10;
                        else cnt <= 10;
                    end else begin
                        cnt <= cnt - 1'b1;
                    end
                end
            end
        end
    end
end

always @(state)
begin
    case(state)
        idle : begin
            red = 0;
            yellow = 0;
            green = 0;
        end
        s1_red : begin
            red = 1;
            yellow = 0;
            green = 0;
        end
        s2_yellow : begin
            red = 0;
            yellow = 1;
            green = 0;
        end
        s3_green : begin
            red = 0;
            yellow = 0;
            green = 1;
        end
        default : begin
            red = 0;
            yellow = 0;
            green = 0;
        end
    endcase
end

always @(posedge clk or negedge rst_n)
begin
    if(!rst_n) begin
        p_red <= red;
        p_yellow <= yellow;
        p_green <= green;
    end else begin
        p_red <= red;
        p_yellow <= yellow;
        p_green <= green;
    end
end

always @(cnt) clock <= cnt;
