module alu(a,b,aluc,r,zero,carry,negative,overflow,flag);
`define ADD 6'b100000
`define ADDU 6'b100001
`define SUB 6'b100010
`define SUBU 6'b100011
`define AND 6'b100100
`define OR 6'b100101
`define XOR 6'b100110
`define NOR 6'b100111
`define SLT 6'b101010
`define SLTU 6'b101011
`define SLL 6'b000000
`define SRL 6'b000010
`define SRA 6'b000011
`define SLLV 6'b000100
`define SRLV 6'b000110
`define SRAV 6'b000111
`define LUI 6'b001111
input [31:0] a;
input [31:0] b;
input [5:0] aluc;
output reg[31:0] r;
output zero, carry, negative, overflow, flag;
reg [32:0] res;
wire signed [31:0] sa = a;
wire signed [31:0] sb = b;
assign {carry, res[31:0]} = res;
assign zero = ~|{res[31:0]};
assign negative = res[31];
assign overflow = (sa[31]&sb[31]& ~res[31]) | (~sa[31]& ~sb[31]& res[31]);
assign flag = (aluc==6'b101010)?res[31]:
                  (aluc==6'b101011)?~|res[31:0]:1'bz;
always @(a or b or aluc) begin
    case(aluc)
    `ADD:  res = sa + sb;
    `ADDU: res = a + b;
    `SUB:  res = sa - sb;
    `SUBU: res = a - b;
    `AND:  res = a & b;
    `OR:   res = a | b;
    `XOR:  res = a ^ b;
    `NOR:  res = ~(a | b);
    `SLT:  res = {1'b0, (sa<sb)};
    `SLTU: res = {1'b0, (a<b)};
    `SLL:  res = b << a[4:0];
    `SRL:  res = b >> a[4:0];
    `SRA:  res = sb >>> a[4:0];
    `SLLV: res = b << a[4:0];
    `SRLV: res = b >> a[4:0];
    `SRAV: res = sb >>> a[4:0];
    `LUI:  res = {a[15:0],16'h0000};
    default: res = 32'bz;
    endcase
    r <= res[31:0];
end
endmodule

