module div_16bit(input [15:0] A, B, output reg [15:0] result, odd) ;
    reg [15:0] a_reg;
    reg [8:0] b_reg;
    integer i;
    always @* begin
        a_reg = A;
        b_reg = B;
    end
    always @* begin
        for (i = 15;
 i > 0;
 i = i - 1) begin
            if (a_reg[i - 1:0] >= b_reg) begin
                result[i] = 1'b1;
                odd = a_reg[i - 1:0] - b_reg;
                a_reg = {odd[i], a_reg[i - 1:1]};
            end else begin
                result[i] = 1'b0;
                odd = a_reg[i - 1:0];
                a_reg = {1'b0, a_reg[i - 1:1]};
            end
        end
        if (a_reg[0] >= b_reg) begin
            result[0] = 1'b1;
            odd = a_reg[0] - b_reg;
        end else begin
            result[0] = 1'b0;
            odd = a_reg[0];
        end
    end
endmodule

