module LIFObuffer (dataIn, RW, EN, Rst, Clk, EMPTY, FULL, dataOut) ;
input [3:0] dataIn ;
input RW, EN, Rst, Clk ;
output EMPTY, FULL ;
output [3:0] dataOut ;
wire [3:0] dataIn ;
wire RW, EN, Rst, Clk ;
reg [3:0] dataOut ;
reg EMPTY, FULL ;
reg [3:0] stack_mem [3:0] ;

reg [2:0] SP = 4 ;

always @ (posedge Clk)
  begin : LIFObuffer
    if (EN) 
      begin
        if (~Rst) 
          begin
            SP = 4 ;
            FULL <= 1'b0 ;
            EMPTY <= 1'b1 ;
            dataOut = 4'h0 ;
            stack_mem[0] = 4'h0 ;
            stack_mem[1] = 4'h0 ;
            stack_mem[2] = 4'h0 ;
            stack_mem[3] = 4'h0 ;
          end
        else
          begin
            if (SP == 4'b0000) 
              begin
                EMPTY <= 1'b1 ;
              end
            else 
              begin
                FULL <= 1'b1 ;
              end
            if (~(RW && FULL))
              begin
                if (SP == 4'b1000) 
                  begin
                    FULL <= 1'b1 ;
                  end
                else 
                  begin
                    stack_mem[SP-1] <= dataIn ;
                    SP = SP - 1 ;
                  end
              end
            if (~(~RW && EMPTY))
              begin
                if (SP == 4'b1000) 
                  begin
                    dataOut <= stack_mem[SP] ;
                    stack_mem[SP] <= 4'h0 ;
                    SP = SP + 1 ;
                  end
                else
                  begin
                    dataOut <= stack_mem[SP] ;
                    stack_mem[SP] <= 4'h0 ;
                    SP = SP + 1 ;
                  end
              end
          end
      end
  end
always @ (EMPTY or FULL or SP)
  begin
    EMPTY = SP[2:1] == 2'b10 ;
    FULL = SP == 4'b0000 ;
  end
endmodule

