module pulse_detect(clk, rst_n, data_in, data_out) ;
    input clk, rst_n, data_in;
    output data_out;
    reg data_out;
    localparam[2:0] INIT = 3'b000;

    localparam[2:0] STATE_1 = 3'b001;

    localparam[2:0] STATE_2 = 3'b010;

    localparam[2:0] STATE_3 = 3'b011;

    localparam[2:0] STATE_4 = 3'b100;

    reg[2:0] state, next_state;

    always @(posedge clk, negedge rst_n)  
    begin
        if (~rst_n) state <= INIT;

        else state <= next_state;

    end
    always @(state, data_in) begin
        case (state)
            INIT: begin
                if (data_in) begin
                    next_state = STATE_1;
                    data_out = 0;
                end else begin
                    next_state = INIT;
                    data_out = 0;
                end
            end
            STATE_1: begin
                if (data_in) begin
                    next_state = STATE_1;
                    data_out = 0;
                end else begin
                    next_state = STATE_2;
                    data_out = 0;
                end
            end
            STATE_2: begin
                if (data_in) begin
                    next_state = STATE_3;
                    data_out = 0;
                end else begin
                    next_state = STATE_2;
                    data_out = 0;
                end
            end
            STATE_3: begin
                if (data_in) begin
                    next_state = STATE_1;
                    data_out = 0;
                end else begin
                    next_state = STATE_4;
                    data_out = 0;
                end
            end
            STATE_4: begin
                if (data_in) begin
                    next_state = STATE_1;
                    data_out = 1;
                end else begin
                    next_state = STATE_4;
                    data_out = 0;
                end
            end
        endcase
    end
endmodule

