module traffic_light
    (
    input clk,
    input rst_n,
    input pass_request,
    output reg [7:0] clock,
    output reg red,
    output reg yellow,
    output reg green
    );
`define idle 2'b00
`define s1_red 2'b01
`define s2_yellow 2'b10
`define s3_green 2'b11
reg [7:0] cnt;
reg [1:0] state;
reg p_red, p_yellow, p_green;
always @(posedge clk or negedge rst_n)
begin
    if (!rst_n)
        state <= `idle;
    else
        case (state)
            `idle:
                state <= `s1_red;
            `s1_red:
                if(cnt <= 3'd3)
                    state <= `s3_green;
                else
                    state <= `s1_red;
            `s2_yellow:
                if(cnt <= 3'd3)
                    state <= `s1_red;
                else
                    state <= `s2_yellow;
            `s3_green:
                if(cnt <= 3'd3)
                    state <= `s2_yellow;
                else
                    state <= `s3_green;
        endcase
end
