begin
    if (!rst_n)
        cnt <= 8'd10;
    else if(pass_request && green)
        cnt <= 8'd10;
    else if(!green && p_green)
        cnt <= 8'd60;
    else if(!yellow && p_yellow)
        cnt <= 8'd5;
    else if(!red && p_red)
        cnt <= 8'd10;
    else if(cnt <= 8'b0)
        cnt <= 8'd10;
    else
        cnt <= cnt - 8'd1;
end
assign clock = cnt;
always @(posedge clk or negedge rst_n)
begin
    if (!rst_n)
    begin
        p_red <= 1'b0;
        p_yellow <= 1'b0;
        p_green <= 1'b0;
    end
    else
    begin
        p_red <= red;
        p_yellow <= yellow;
        p_green <= green;
    end
end
