    if (cnt == 8'd3)
        yellow = 1'b1;
    else
        yellow = 1'b0;
end
always @*
begin
    if (cnt == 8'd3)
        red = 1'b0;
    else
        red = 1'b1;
end
always @*
begin
    if (cnt == 8'd0)
        green = 1'b1;
    else
        green = 1'b0;
end
