module alu(a, b, aluc, r, zero, carry, negative, overflow, flag) ;
    input [31:0] a, b;
    input [5:0] aluc;
    output [31:0] r;
    output zero, carry, negative, overflow, flag;
    reg [32:0] res;
    reg flag_tmp;
    wire [32:0] a_temp, b_temp;
    parameter ADD = 6'b100000;
    parameter SUB = 6'b100010;
    parameter AND = 6'b100100;
    parameter OR = 6'b100101;
    parameter XOR = 6'b100110;
    parameter NOR = 6'b100111;
    parameter SLT = 6'b101010;
    assign a_temp = $signed(a);
    assign b_temp = $signed(b);
    assign flag = flag_tmp;
    assign r = res[31:0];
    assign zero = (r == 0);
    assign overflow = (a[31] == b[31]) && (a[31] != r[31]);
    assign negative = r[31];
    assign carry = res[32];
    always @(*)
    begin
      case(aluc)
        ADD:  begin res = a_temp + b_temp;
                flag_tmp = 1'b0;
              end
        SUB:  begin res = a_temp - b_temp;
                flag_tmp = 1'b0;
              end
        AND:  begin res = a_temp & b_temp;
                flag_tmp = 1'b0;
              end
        OR:   begin res = a_temp | b_temp;
                flag_tmp = 1'b0;
              end
        XOR:  begin res = a_temp ^ b_temp;
                flag_tmp = 1'b0;
              end
        NOR:  begin res = ~(a_temp | b_temp);
                flag_tmp = 1'b0;
              end
        SLT:  begin res = (a_temp < b_temp) ? 1'b1 : 1'b0;
                flag_tmp = 1'b1;
              end
        default: begin res = 32'bx;
                flag_tmp = 1'b0;
              end
      endcase
    end
endmodule

