module radix2_div
(
    clk,
    rst,
    sign,
    dividend,
    divisor,
    opn_valid,
    res_valid,
    result
) ;
input           clk, rst ;
input           sign ;
input   [7:0]   dividend, divisor ;
input           opn_valid ;
output          res_valid ;
output  [15:0]  result ;

reg     [7:0]   SR ;

reg     [8:0]   NEG_DIVISOR ;
wire    [8:0]   SUB = { SR[7],SR[7:0] } - { { 1'b0,NEG_DIVISOR[7:0] } } ;

wire    [1:0]   mux_OUT ;
wire            CRY ;
assign  mux_OUT[0] = ( sign && ( SUB[8] ) ) ? 1'b1 : 1'b0 ;
assign  mux_OUT[1] = ( ~SUB[8] ) ? 1'b1 : 1'b0 ;
assign  CRY = ( ~( sign & NEG_DIVISOR[8] ) & SUB[8] ) ? 1'b1 : 1'b0 ;

reg     [3:0]   cnt ;
wire            isMax ;
assign  isMax = ~( |cnt[3:0] ) ;
reg             start_cnt ;
always @( posedge clk or posedge rst )
    if ( rst ) begin
        cnt <= 4'd0 ;
        start_cnt <= 1'd0 ;
    end else
        if ( opn_valid && ~res_valid ) begin
            cnt <= 4'd1 ;
            start_cnt <= 1'd1 ;
        end else
            if ( start_cnt ) begin
                if ( isMax )
                    start_cnt <= 1'd0 ;
                else
                    cnt <= cnt + 1'b1 ;
            end

reg             valid ;
reg             consumed ;
always @( posedge clk or posedge rst )
    if ( rst ) begin
        valid <= 1'd0 ;
        consumed <= 1'd0 ;
    end else
        case ( { isMax,consumed } )
        2'b10: begin
            valid <= res_valid ;
            consumed <= res_valid ;
        end
        2'b01: begin
            valid <= res_valid ;
            consumed <= res_valid ;
        end
        2'b11: begin
            valid <= 1'd0 ;
            consumed <= 1'd0 ;
        end
        2'b00: begin
            valid <= res_valid ;
            consumed <= res_valid ;
        end
        endcase
assign  res_valid = valid ;

wire    [8:0]   SR_IN ;
assign  SR_IN[8] = CRY ;
assign  SR_IN[7:0] = SR[7:0] ;
always @( posedge clk )
    if ( opn_valid && ~res_valid ) begin
        NEG_DIVISOR[7:0] <= ( sign ) ? { 1'b1,~divisor[7:0] } : divisor[7:0] ;
        NEG_DIVISOR[8]   <= ( sign ) ? ( divisor[7] ) : 1'b0 ;
        SR[7:0]          <= ( sign ) ? { 1'b1,~dividend[7:0] } : dividend[7:0] ;
        SR[8]            <= ( sign ) ? dividend[7] : 1'b0 ;
    end else
        if ( start_cnt ) begin
            SR[7:0] <= SR_IN[7:0] << 1 ;
            SR[8] <= SR_IN[8] ;
        end

reg     [15:0]  result ;
wire    [15:0]  div_abs ;
assign  div_abs[15:8] = SR[8] ? { 1'b0,NEG_DIVISOR[7:0] } : NEG_DIVISOR[7:0] ;
assign  div_abs[7:0] = SR[8] ? SR[7:0] : SR[7:0] + 1 ;
always @( posedge clk or posedge rst )
    if ( rst ) begin
        result <= 16'd0 ;
    end else
        case ( ~{ isMax,consumed } )
        2'b10: begin
            result <= { 8'd0,SR[7:0] } ;
        end
        2'b01: begin
            if ( sign )
                result <= { ~div_abs[15:8],SR[7:0] } ;
            else
                result <= div_abs[15:0] ;
        end
        endcase
