    assign of1 = (A[63] == 1'b0 && B[63] == 1'b1 && result_tmp[63] == 1'b1) ? 1'b1 : 1'b0 ;
    assign of2 = (A[63] == 1'b1 && B[63] == 1'b0 && result_tmp[63] == 1'b0) ? 1'b1 : 1'b0 ;
    assign overflow = of1 || of2 ;
    assign result = result_tmp ;
