    input      IN,
    input      CLK,
    input      RST,
    output reg MATCH
) ;
  reg [3:0] state;
  parameter [3:0]   STATE_0  = 4'b0000,
                    STATE_1  = 4'b0001,
                    STATE_2  = 4'b0010,
                    STATE_3  = 4'b0011,
                    STATE_4  = 4'b0100,
                    STATE_5  = 4'b0101,
                    STATE_6  = 4'b0110,
                    STATE_7  = 4'b0111,
                    STATE_8  = 4'b1000,
                    STATE_9  = 4'b1001,
                    STATE_10 = 4'b1010,
                    STATE_11 = 4'b1011;
  reg [3:0] state_next;
  always @(posedge CLK) begin
    state <= (RST) ? STATE_0 : state_next;
  end
  always @(state, IN) begin
    state_next = state;
    MATCH      = 1'b0;
    case (state)
      STATE_0: state_next = (IN) ? STATE_1 : STATE_0;
      STATE_1: state_next = (IN) ? STATE_2 : STATE_0;
      STATE_2: state_next = (IN) ? STATE_2 : STATE_3;
      STATE_3: state_next = (IN) ? STATE_4 : STATE_0;
      STATE_4: state_next = (IN) ? STATE_2 : STATE_5;
      STATE_5: state_next = (IN) ? STATE_6 : STATE_0;
      STATE_6: state_next = (IN) ? STATE_7 : STATE_0;
      STATE_7: state_next = (IN) ? STATE_8 : STATE_5;
      STATE_8: state_next = (IN) ? STATE_2 : STATE_9;
      STATE_9: state_next = (IN) ? STATE_10 : STATE_0;
      STATE_10: state_next = (IN) ? STATE_11 : STATE_5;
      STATE_11: begin
        state_next = (IN) ? STATE_8 : STATE_0;
        MATCH = 1'b1;
      end
      default: state_next = STATE_0;
    endcase
  end
