                    begin
                        out = 0;
                        if(data_in)
                            next_state = S1;
                        else
                            next_state = IDLE;
                    end
                S1:
                    begin
                        out = 0;
                        if(data_in)
                            next_state = S1;
                        else
                            next_state = S2;
