                S2:
                    begin
                        out = 0;
                        if(data_in)
                            next_state = S3;
                        else
                            next_state = IDLE;
                    end
                S3:
                    begin
                        out = 0;
                        if(data_in)
                            next_state = S1;
                        else
                            next_state = S4;
                    end
                S4:
                    begin
                        out = 1;
                        if(data_in)
                            next_state = S1;
                        else
                            next_state = S2;
                    end
                default:
                    begin
                        out = 0;
                        next_state = IDLE;
                    end
            endcase
        end
    assign sequence_detected = out;
