module LIFObuffer(dataIn, RW, EN, Clk, Rst, EMPTY, FULL, dataOut) ;
input [3:0] dataIn ;
input RW, EN, Clk, Rst ;
output EMPTY, FULL ;
output [3:0] dataOut ;
wire [3:0] dataIn ;
wire RW, EN, Clk, Rst ;
wire EMPTY, FULL ;
reg [3:0] dataOut ;
reg [3:0] stack_mem [0:3] ;

reg [1:0] SP ;

integer k,k1;


assign EMPTY = (SP[0])&(SP[1]);
assign FULL = !(SP[0])&(SP[1]);
always @ (posedge Clk)
begin
    if(EN)
    begin
        if(Rst)
        begin
            for (k=0 ;
 k<4 ;
 k=k+1)
                begin
                    stack_mem[k] = 0;
                end
            SP = 4;
            dataOut = 4'bxxxx;
        end
        else
        begin
            if(!RW && !FULL) 
            begin
                SP = SP - 1;
                for (k=0 ;
 k<4 ;
 k=k+1)
                begin
                    stack_mem[k][0] = stack_mem[k][1];
                    stack_mem[k][1] = stack_mem[k][2];
                    stack_mem[k][2] = stack_mem[k][3];
                    stack_mem[k][3] = 1'b0;
                end
                for (k=0 ;
 k<4 ;
 k=k+1)
                begin
                    if(stack_mem[k][0] == 0)
                    begin
                        stack_mem[k][0] = dataIn[k];
                        stack_mem[k][1] = dataIn[k];
                        stack_mem[k][2] = dataIn[k];
                        stack_mem[k][3] = dataIn[k];
                    end
                end
            end
            else if(RW && !EMPTY) 
            begin
                for(k1=0 ;
 k1<4 ;
 k1=k1+1)
                begin
                    for (k=0 ;
 k<4 ;
 k=k+1)
                    begin
                        if(stack_mem[k][0] == 1'b1)
                        begin
                            dataOut[k] = stack_mem[k][k1];
                        end
                        stack_mem[k][k1] = 0;
                    end
                end
                SP = SP + 1;
            end
            else
            begin
                dataOut = dataOut;
            end
        end
    end
end
endmodule

