module pulse_detect(clk, rst_n, data_in, data_out) ;
input       clk, rst_n;
input       data_in;
output  data_out;

parameter   zero=3'b000,  
            s0=3'b001,  
            s1=3'b010,  
            s2=3'b011,  
            s3=3'b100,  
            s4=3'b101,  
            last=3'b110,
            s5=3'b111;

wire  last_data;
assign last_data = data_in ? s1 : s0;

reg data_out;

reg [2:0] state;

reg [2:0] next_state;
always @ (posedge clk or negedge rst_n)  
  begin
    if (~rst_n)  
        begin
            state <= zero;

            data_out <= 0;
        end
    else
        begin
            state <= last_data;
        end
  end

always @ (*)  
begin
    case (state)
    zero:  
        next_state = data_in ? zero : s0;

    s0:  
        next_state = data_in ? s1 : s0;

    s1:  
        next_state = data_in ? s2 : s0;

    s2:  
        next_state = data_in ? s3 : s0;
    s3:  
        next_state = data_in ? s4 : s0;

    s4:
        next_state = data_in ? s5 : s0;

    s5:  
        next_state = data_in ? last : s0;

    last:  
        next_state = data_in ? last : s0;

    default:
        next_state = 3'bxxx;
    endcase
end


always @ (*)  
begin
    case (state)
    zero:  
        data_out = 0;

    s0:  
        data_out = 0;

    s1:  
        data_out = 0;
    s2:  
        data_out = 0;

    s3:  
        data_out = 0;
    s4:  
        data_out = 0;

    s5:  
        data_out = 0;

    last:  
        data_out = 1;

    default:
        data_out = 0;
    endcase
end
endmodule

