`define ADDU 6'b100001
`define SUB 6'b100010
`define SUBU 6'b100011
`define AND 6'b100100
`define OR 6'b100101
`define XOR 6'b100110
`define NOR 6'b100111
`define SLT 6'b101010
`define SLTU 6'b101011
`define SLL 6'b000000
`define SRL 6'b000010
`define SRA 6'b000011
`define SLLV 6'b000100
`define SRLV 6'b000110
`define SRAV 6'b000111
`define LUI 6'b001111
wire signed [31:0] signed_a, signed_b;
assign signed_a = a;
assign signed_b = b;
assign zero = (r == 32'b0) ? 1 : 0;
assign flag = ((aluc == 6'b101010) || (aluc == 6'b101011)) ? res[0] : 1'bz;
always@(*) begin
    case (aluc)
        `ADD: res = a + b;
        `ADDU: res = a + b;
        `SUB: res = a - b;
        `SUBU: res = a - b;
        `AND: res = a & b;
        `OR: res = a | b;
        `XOR: res = a ^ b;
        `NOR: res = ~(a | b);
        `SLT: res = (signed_a < signed_b) ? 1 : 0;
        `SLTU: res = (a < b) ? 1 : 0;
        `SLL: res = b << a[4:0];
        `SRL: res = b >> a[4:0];
        `SRA: res = signed_b >>> a[4:0];
        `SLLV: res = b << a[4:0];
        `SRLV: res = b >> a[4:0];
        `SRAV: res = signed_b >>> a[4:0];
        `LUI: res = {a[15:0], 16'b0};
        default: res = 32'bz;
    endcase
    r[31:0] = res[31:0];
    carry = (aluc == 6'b100000 || aluc == 6'b100010) ? res[32] : 1'bz;
    negative = (aluc == 6'b101010 || aluc == 6'b101011) ? res[0] : 1'bz;
end
