module radix2_div (
    clk,
    rst,
    sign,
    dividend,
    divisor,
    opn_valid,
    res_valid,
    result
) ;
input clk;
input rst;
input sign;
input [7 : 0] dividend;
input [7 : 0] divisor;
input opn_valid;
output res_valid;
output [15 : 0] result;
reg [8 : 0] SR;
reg [3 : 0] cnt;
reg [7 : 0] DIVIDEND;
reg [7 : 0] DIVISOR;
reg [7 : 0] NEG_DIVISOR;
reg [7 : 0] Q;
reg start_cnt;
wire [8 : 0] sub_result;
wire carry;
always @(posedge clk or negedge rst)
begin
    if (rst == 0) 
    begin
        SR[8 : 1] <= 0;
        DIVIDEND <= 0;
        DIVISOR <= 0;
        NEG_DIVISOR <= 0;
        cnt <= 0;
        Q <= 0;
        start_cnt <= 0;
    end
    else 
    begin
        if (opn_valid)
        begin
            DIVIDEND <= dividend;
            DIVISOR <= divisor;
            start_cnt <= 0;
            cnt <= 1;
            if (sign) 
            begin
                SR[8 : 1] <= (dividend < divisor) ? ({1'b0, dividend[7 : 0]}) : ({1'b1, dividend[7 : 0]});
                NEG_DIVISOR <= (dividend < divisor) ? ({1'b0, divisor[7 : 0]}) : (~divisor[7 : 0] + 1);
            end
            else 
            begin
                SR[8 : 1] <= {1'b0, dividend[7 : 0]};
                NEG_DIVISOR <= (~divisor[7 : 0] + 1);
            end
        end
        else 
        begin
            if (cnt != 0 && start_cnt)
            begin
                if (cnt[3]) 
                begin
                    Q <= SR[8 : 1];
                    cnt <= 0;
                    start_cnt <= 0;
                end
                else 
                begin
                    cnt <= cnt + 1;
                    if (sub_result[8] == 0) 
                    begin
                        SR[8 : 1] <= {sub_result[7 : 0], carry};
                    end
                    else 
                    begin
                        SR[8 : 1] <= {SR[8 : 1]};
                    end
                end
            end
        end
    end
end

wire [8 : 0] sub_result = SR[15 : 8] - NEG_DIVISOR;
assign carry = sub_result[8];
assign result = {carry == 1'b1, Q};
assign res_valid = cnt != 0;
endmodule

