module div_16bit(
                 A,                   
                 B,                   
                 result,              
                 odd                  
                 ) ;
parameter Abit = 16 ;
parameter Bbit = 8 ;
input  [Abit-1:0] A ;
input  [Bbit-1:0] B ;
output [Abit-1:0] result ;
output [Abit-1:0] odd ;
reg [Abit-1:0] odd ;
reg [Abit-1:0] a_reg ;
reg [Bbit-1:0] b_reg ;
reg [Abit-1:0] result ;
reg [Abit-1:0] del_a ;
reg [Bbit-1:0] del_b ;
reg [Abit-1:0] diff ;
reg [Abit-1:0] answer ;
reg [Bbit-1:0] bsave ;
reg [Bbit:0]  bsegsave;
integer i ;
always @(A or B) begin
    a_reg  = A ;
    b_reg  = B ;
end
always @(a_reg or b_reg) begin
    bsave = b_reg ;
    bsegsave = 0 ;
    diff = a_reg[Abit-1:Abit-Bbit] ;
    for(i=0;
 i<Abit;
 i=i+1) begin
        answer = 0 ;
        if (diff >= b_reg) begin
            answer = 1 ;
            diff = diff - b_reg ;
        end
        else begin
            answer = 0 ;
        end
        bsegsave = bsegsave << 1 ;
        bsegsave[0] = answer ;
        bsegsave = bsegsave >> 1 ;
        bsave = bsave >> 1 ;
        bsave = bsave | (bsegsave<<(Bbit-1)) ;
        b_reg  = bsave ;
        diff   = diff << 1 ;
        diff   = diff | (a_reg[Abit-1-i] ) ;
    end
    odd = diff ;
    for (i=0;
 i<Abit;
 i=i+1) begin
        result[Abit-1-i] = bsegsave[Bbit-1-i] ;
    end
end
endmodule

