module fixed_point_adder (
    input [N-1:0] a, b,
    output [N-1:0] c
);
parameter Q = 2;

parameter N = 5;

reg [N-1:0] res;


always @(a, b)
begin
    if (a[N-2:0] > b[N-2:0]) begin
        res[N-2:0] = a[N-2:0] - b[N-2:0];
        res[N-1] = a[N-1];
    end else begin
        res[N-2:0] = b[N-2:0] - a[N-2:0];
        res[N-1] = b[N-1];
    end
    if (a[N-1] == b[N-1]) begin 
        res[N-1] = a[N-1];
    end else begin
        if (a > b) begin 
            res[N-1] = a[N-1];
        end else begin
            res[N-1] = b[N-1];
        end
    end

    if (res[N-1] && !(|res[N-2:0])) begin
        res[N-1] = 1'b0;
    end else if (!res[N-1] && (&res[N-2:0])) begin
        res[N-1] = 1'b1;
    end
end
assign c = res;
endmodule

