module sub_64bit(
    A, 
    B, 
    result, 
    overflow
) ;
    input [63 : 0] A;
    input [63 : 0] B;
    output [63 : 0] result;
    output overflow;
    wire [63 : 0] result_tmp;
    wire pos_overflow;
    wire neg_overflow;
    assign result_tmp = A - B;
    assign pos_overflow = (A[63] == 1'b0 && B[63] == 1'b1 && result_tmp[63] == 1'b1);
    assign neg_overflow = (A[63] == 1'b1 && B[63] == 1'b0 && result_tmp[63] == 1'b0);
    assign overflow = pos_overflow || neg_overflow;
    assign result = result_tmp;
endmodule

