module fsm(IN, CLK, RST, MATCH) ;
parameter   S0=0, S1=1, S2=2, S3=3, S4=4 ;
parameter   INS=1, INN=0 ;

input IN, CLK, RST ;

output  MATCH ;
reg  MATCH ;
reg [2:0] CURR ;
reg [2:0] NEXT ;
always @(posedge CLK or posedge RST) begin
    if (RST)
        CURR <= S0 ;
    else
        CURR <= NEXT ;
end
always @(IN or CURR)
begin
    case (CURR)
        S0 : begin
            if( IN == INS )
                NEXT = S1 ;
            else
                NEXT = S0 ;
        end
        S1 : begin
            if ( IN == INN ) 
                NEXT = S2 ;
            else
                NEXT = S1 ;
        end
        S2 : begin
            if( IN == INN )
                NEXT = S3 ;
            else
                NEXT = S1 ;
        end
        S3 : begin
            if( IN == INS ) 
                NEXT = S4 ;
            else
                NEXT = S0 ;
        end
        S4 : begin
            if( IN == INS )
                NEXT = S1 ;
            else
                NEXT = S0 ;
        end
        default : NEXT = S0 ;
    endcase
end
always @ (IN or CURR)
begin
    if ( CURR == S4 && IN == INS )
        MATCH = 1 ;
    else
        MATCH = 0 ;
end
