    reg [31:0] temp_1, temp_2 ;
    wire [4:0] shamt ;
    wire cin ;
    assign shamt = a[4:0] ;
    assign cin = 0 ;
    assign flag = res[31] ? 1'b1 : 1'b0 ;
    assign zero = (res[31:0] == 32'b0) ? 1'b1 : 1'b0;
    assign carry = res[32];
