            ADDU:  res = a + b ;
            SUB:   res = a - b ;
            SUBU:  res = a - b ;
            AND:   res = a & b ;
            OR:    res = a | b ;
            XOR:   res = a ^ b ;
            NOR:   res = ~(a | b) ;
            SLT:   res = a_us > b_us ? 32'b1 : 32'b0 ;
            SLTU:  res = a > b ? 32'b1 : 32'b0 ;
            SLL:   res = b << shamt ;
            SRL:   res = b >> shamt ;
