module div_16bit (
    input  [15:0] A,
    input  [7:0]  B,
    output [15:0] result,
    output [15:0] odd
) ;
    reg [15:0] a_reg;
    reg [7:0]  b_reg;
    reg [15:0] work;
    always @(A,B) begin
        a_reg = A;
        b_reg = B;
    end
    always @(A,B) begin
        if (a_reg[15:8] >= b_reg) begin
            work = {8'b0, a_reg[15:8] - b_reg};
            a_reg = {work[7:0], a_reg[7:0]};
        end
        if (a_reg[15:12] >= b_reg) begin
            work = {4'b0, a_reg[15:12] - b_reg};
            a_reg = {work[3:0], a_reg[11:0]};
        end
        if (a_reg[15:14] >= b_reg) begin
            work = {2'b0, a_reg[15:14] - b_reg};
            a_reg = {work[1:0], a_reg[13:0]};
        end
        if (a_reg[15] >= b_reg) begin
            work = {1'b0, a_reg[15] - b_reg};
            a_reg = {work[0], a_reg[14:0]};
        end
    end
    assign result = a_reg[15:0];
    assign odd = {a_reg[0], 15'b0};
endmodule

