module LIFObuffer(dataIn,RW,EN,Rst,Clk,EMPTY,FULL,dataOut) ;
  input [3:0] dataIn ;
  input RW,EN,Rst,Clk ;

  output EMPTY,FULL ;
  output [3:0] dataOut ;
  wire EMPTY,FULL ;
  wire [3:0] dataOut ;
  reg [3:0] SP ;

  reg [3:0] stack_mem [3:0];
  reg [3:0] MuxOut ;
  always @(posedge Clk)
  begin
    if(EN) begin
      if(Rst) begin
        SP<=4'd4;
        stack_mem[0]<=4'd0;
        stack_mem[1]<=4'd0;
        stack_mem[2]<=4'd0;
        stack_mem[3]<=4'd0;
        MuxOut<=4'd0;
      end
      else begin
        if(!RW && (SP>4'd0)) begin 
          SP<=SP-1'b1;
          stack_mem[SP]<=dataIn;
        end
        if(RW && (SP<4'd4)) begin 
          dataOut<=stack_mem[SP];
          stack_mem[SP]<=4'd0;
          SP<=SP+1'b1;
        end
      end
    end
    else begin
      SP<=SP;
      stack_mem[0]<=stack_mem[0];
      stack_mem[1]<=stack_mem[1];
      stack_mem[2]<=stack_mem[2];
      stack_mem[3]<=stack_mem[3];
    end
  end
  assign EMPTY=(SP==4'd4)?1'b1:1'b0;
  assign FULL=(SP==4'd0)?1'b1:1'b0;
endmodule

