module pulse_detect(clk, rst_n, data_in, data_out) ;
input		clk, rst_n ;
input 	[3:0] data_in ;
output reg [3:0] data_out ;
reg [3:0] state ;
reg [3:0] next_state ;
always@(*)begin 
	case(state)
		4'h0:begin
			if(data_in) 
				next_state = 4'h1;
			else 
				next_state = 4'h0;
		end
		4'h1:begin
			if(data_in) 
				next_state = 4'h2;
			else 
				next_state = 4'h0;
		end
		4'h2:begin
			if(data_in) 
				next_state = 4'h3;
			else 
				next_state = 4'h0;
		end
		4'h3:begin
			if(data_in) 
				next_state = 4'h4;
			else 
				next_state = 4'h0;
		end
		4'h4:begin
			if(data_in) 
				next_state = 4'h5;
			else 
				next_state = 4'h0;
		end
		4'h5:begin
			if(data_in) 
				next_state = 4'h1;
			else 
				next_state = 4'h0;
		end
		default: begin 
			next_state = 4'h0;
		end
	endcase 
end
always@(posedge clk or negedge rst_n) begin 
	if(~rst_n) begin 
		state <= 4'h0;
	end else begin 
		state <= next_state;
	end 
end
always @(posedge clk or negedge rst_n) begin
	if(~rst_n) begin 
		data_out <= 4'h0;
	end 
	else begin 
		if(state[0] & (~next_state[0])) begin 
			data_out <= 1;
		end
		else begin 
			data_out <= 0;
		end 
	end 
end
endmodule

