module traffic_light(input clk, rst_n, pass_request,
                     output [7:0] clock,
                     output red, yellow, green);
`define idle 2'b00
`define s1_red 2'b01
`define s2_yellow 2'b10
`define s3_green 2'b11
reg [7:0] cnt = 8'd60;
reg [1:0] state = `idle;
reg p_red = 1'b0;
reg p_yellow = 1'b0;
reg p_green = 1'b0;
always @(posedge clk or negedge rst_n) begin
    if(!rst_n) 
        state <= `idle;
    else case(state)
        `idle:
            state <= `s1_red;
        `s1_red: begin
            if(cnt > 3'd3)
                state <= `s1_red;
            else
                state <= `s2_yellow;
        end
        `s2_yellow: begin
            if(cnt > 3'd3)
                state <= `s2_yellow;
            else
                state <= `s3_green;
        end
        `s3_green: begin
            if(cnt > 3'd3)
                state <= `s3_green;
            else
                state <= `s1_red;
        end
        default:
            state <= `idle;
    endcase
end
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) cnt <= 8'd60;
    else if(pass_request && p_green) cnt <= 8'd10;
    else if((!p_green) && p_yellow) cnt <= 8'd5;
    else if((!p_yellow) && p_red) cnt <= 8'd10;
    else if(cnt > 8'd0) cnt <= cnt - 8'b1;
end
assign clock = cnt;
always @(posedge clk or negedge rst_n) begin
    if(!rst_n) begin
        p_red <= 1'b0;
        p_yellow <= 1'b0;
        p_green <= 1'b0;
    end else begin
        p_red <= red;
        p_yellow <= yellow;
        p_green <= green;
    end
end
assign red = (state == `s1_red || state == `s2_yellow);
assign yellow = (state == `s2_yellow);
assign green = (state == `s3_green);
endmodule

