module alu(input [31:0] a, b, input [5:0] aluc, output reg [31:0] r, output zero, carry, negative, overflow, flag) ;

    parameter ADD = 6'b100000;
    parameter ADDU = 6'b100001;
    parameter SUB = 6'b100010;
    parameter SUBU = 6'b100011;
    parameter AND = 6'b100100;
    parameter OR = 6'b100101;
    parameter XOR = 6'b100110;
    parameter NOR = 6'b100111;
    parameter SLT = 6'b101010;
    parameter SLTU = 6'b101011;
    parameter SLL = 6'b000000;
    parameter SRL = 6'b000010;
    parameter SRA = 6'b000011;
    parameter SLLV = 6'b000100;
    parameter SRLV = 6'b000110;
    parameter SRAV = 6'b000111;
    parameter LUI = 6'b001111;

    wire signed [31:0] a_signed, b_signed;
    reg [31:0] res;

    assign a_signed = a;
    assign b_signed = b;

    assign r = res[31:0];

    assign flag = aluc[5] ? 1'bz : 
                  aluc == SLT ? (($signed(a_signed) < $signed(b_signed)) ? 1 : 0) :
                  aluc == SLTU ? ((a < b) ? 1 : 0) :
                  1'bz;

    assign zero = (res == 32'b0) ? 1'b1 : 1'b0;

    always @(a, b, aluc)
    begin
        case (aluc)
        ADD, ADDU, SUB, SUBU: 
        begin
            if (aluc == SUB || aluc == SUBU)
                res = a + (~b+1);

            else if (aluc == ADD || aluc == ADDU)
                res = a + b;
        end
        AND, OR, XOR, NOR:
        begin
            if (aluc == AND)
                res = a & b;
            else if (aluc == OR)
                res = a | b;
            else if (aluc == XOR)
                res = a ^ b;
            else if (aluc == NOR)
                res = ~(a | b);
        end
        SLL, SLLV:
        begin
            res = b << a[4:0];
        end
        SRL, SRLV:
        begin
            res = b >> a[4:0];
        end
        SRA, SRAV:
        begin
            res = b_signed >>> a[4:0];

        end
        LUI:
        begin
            res = {a[15:0], 16'b0};
        end
        default:
        begin
            res = 32'bz;

        end
        endcase
    end
endmodule

