module freq_divbyfrac (
    input  clk,
    input  rst_n,
    output clk_div
) ;
parameter   MUL2_DIV_CLK     =    7   ;
parameter   MUL2_HALF_DIV_CLK    =    MUL2_DIV_CLK/2  ;
parameter   MUL2_ONE4TH_DIV_CLK  =    MUL2_DIV_CLK/4  ;
reg     [2:0]   clk_cnt_d;
reg     [2:0]   clk_cnt_q;
reg             clk_p1_d;
reg             clk_p1_q;
reg             clk_p2_d;
reg             clk_p2_q;
