    if (~rst_n) begin
        clk_cnt_q <= 'd0;
        clk_p1_q  <= 'd0;
        clk_p2_q  <= 'd0;
    end else begin
        clk_cnt_q <= clk_cnt_d;
        clk_p1_q  <= clk_p1_d;
        clk_p2_q  <= clk_p2_d;
    end
end
always @ ( * ) begin
    if (clk_cnt_q == MUL2_DIV_CLK) begin
        clk_cnt_d = 'd1;
        clk_p1_d = (clk_cnt_q <= MUL2_HALF_DIV_CLK);
        clk_p2_d = (clk_cnt_q > MUL2_HALF_DIV_CLK);
    end else begin
        clk_cnt_d = clk_cnt_q + 1'b1;
        clk_p1_d = clk_p1_q;
        clk_p2_d = clk_p2_q;
    end
end
assign clk_div1 = clk & clk_p1_q;
assign clk_div2 = clk & clk_p2_q;
assign clk_div  = clk_div1 | clk_div2;
