module radix2_div
(
    clk,
    rst,
    sign,
    dividend,
    divisor,
    opn_valid,
    res_valid,
    result
)
;
    input   clk;
    input   rst;
    input   sign;
    input   [7:0]  dividend;
    input   [7:0]  divisor;
    input   opn_valid;
    output   res_valid;
    output   [15:0]  result;
    reg [7:0]    REM_OP;
    wire    [7:0]    NEG_DIVISOR;
    wire    [7:0]    DIFF;
    wire    [8:0]    SR;
    wire    carry_out;
    reg    [8:0]    SR_R;
    reg [3:0]    cnt;
    wire    [3:0]    cnt_mux;
    reg    start_cnt;
    wire [7:0] ABS_DIVIDEND;
    wire [7:0] ABS_DIVISOR;
    always @ (posedge clk) begin
        if (rst == 1) begin
            REM_OP = 0;
        end
        else begin
            if (opn_valid == 1) begin
                REM_OP = dividend;
            end
        end
    end
    assign ABS_DIVIDEND = (sign == 0)? dividend : ((dividend[7] == 1)? ~dividend : dividend);
    assign ABS_DIVISOR = (sign == 0)? divisor : ((divisor[7] == 1)? ~divisor : divisor);
    assign cnt_mux = (cnt == 8)? 0 : cnt + 1;
    always @ (posedge clk) begin
        if (rst == 1) begin
            cnt = 0;
        end
        else begin
            if (start_cnt == 1) begin
                cnt = cnt_mux;
            end
        end
    end
    always @ (posedge clk) begin
        if (rst == 1) begin
            start_cnt = 0;
        end
        else begin
            if (opn_valid == 1) begin
                start_cnt = 1;
            end
            else begin
                if (cnt == 8) begin
                    start_cnt = 0;
                end
                else begin
                    start_cnt = start_cnt;
                end
            end
        end
    end
    always @ (posedge clk) begin
        if (rst == 1) begin
            SR_R = 0;
        end
        else begin
            if (opn_valid == 1) begin
                SR_R = {1'b0, ABS_DIVIDEND};
            end
            else begin
                if (start_cnt == 1) begin
                    SR_R = {carry_out, SR[7:0]};
                end
            end
        end
    end
    assign SR = SR_R;
    assign res_valid = ((rst == 0) & ((cnt == 8) | (cnt == 0)));
    assign NEG_DIVISOR = ~divisor + 1;
    assign DIFF = SR[7:0] + NEG_DIVISOR;
    assign carry_out = DIFF[7];
    assign result = ((sign == 0)? {SR[8:1], carry_out} : 
                    ((dividend[7] == 0)? {REM_OP, SR[8:1]} : 
                    ((divisor[7] == 0)? {REM_OP, SR[8:1]} : 
                    ((dividend[7] == 1)? {~REM_OP, SR[8:1]} : {~REM_OP, SR[8:1]}))));
endmodule

