module LIFObuffer (
    dataIn, RW, EN, Rst, Clk, 
    EMPTY, FULL, dataOut
) ;
    input [3:0] dataIn ;
    input RW, EN, Rst, Clk ;
    output EMPTY, FULL ;
    output [3:0] dataOut ;
    reg [3:0] dataOut ;
    reg EMPTY, FULL;
    reg [3:0] stack_mem [0:4] ;
    integer SP ;
    always @(posedge Clk) begin
        if (EN) begin
            if (Rst) begin
                SP <= 4 ;
                EMPTY <= 1'b1 ;
                FULL <= 1'b0 ;
                dataOut <= 4'b0000 ;
                stack_mem[0] <= 4'b0000 ;
                stack_mem[1] <= 4'b0000 ;
                stack_mem[2] <= 4'b0000 ;
                stack_mem[3] <= 4'b0000 ;
                stack_mem[4] <= 4'b0000 ;
            end else begin
                if (~(RW & EMPTY)) begin
                    if (SP == 0) begin
                        FULL <= 1 ;
                        EMPTY <= 0 ;
                        if(RW == 1) begin
                            dataOut <= stack_mem[SP] ;
                            SP = SP + 1 ;
                        end else begin
                            stack_mem[SP] <= dataIn ;
                            SP = SP - 1 ;
                        end
                    end else begin
                        FULL <= 0 ;
                        EMPTY <= 0 ;
                        if (RW == 1) begin
                            dataOut <= stack_mem[SP] ;
                            stack_mem[SP] <= 4'b0000 ;
                            SP = SP + 1 ;
                        end else begin
                            stack_mem[SP] <= dataIn ;
                            SP = SP - 1 ;
                        end
                    end
                end
            end
        end
    end
endmodule

