module pulse_detect(clk, rst_n, data_in, data_out) ;
    input clk, rst_n, data_in;
    output data_out;
    reg data_out;
    reg [2:0] state;
    always @ (posedge clk or negedge rst_n) begin
        if (~rst_n) begin
            state <= 3'b000;
            data_out <= 1'b0;

        end else begin
            case (state)
                3'b000: begin
                    if (data_in == 1'b0) begin
                        state <= 3'b001;
                        data_out <= 1'b0;

                    end else begin
                        state <= 3'b000;
                        data_out <= 1'b0;

                    end
                end
                3'b001: begin
                    if (data_in == 1'b1) begin
                        state <= 3'b010;
                        data_out <= 1'b0;

                    end else begin
                        state <= 3'b001;
                        data_out <= 1'b0;

                    end
                end
                3'b010: begin
                    if (data_in == 1'b0) begin
                        state <= 3'b011;
                        data_out <= 1'b0;

                    end else begin
                        state <= 3'b000;
                        data_out <= 1'b0;

                    end
                end
                3'b011: begin
                    if (data_in == 1'b1) begin
                        state <= 3'b100;
                        data_out <= 1'b1;

                    end else begin
                        state <= 3'b001;
                        data_out <= 1'b0;

                    end
                end
                3'b100: begin
                    if (data_in == 1'b0) begin
                        state <= 3'b101;
                        data_out <= 1'b0;

                    end else begin
                        state <= 3'b000;
                        data_out <= 1'b0;

                    end
                end
                3'b101: begin
                    if (data_in == 1'b1) begin
                        state <= 3'b110;
                        data_out <= 1'b0;

                    end else begin
                        state <= 3'b001;
                        data_out <= 1'b0;

                    end
                end
                3'b110: begin
                    if (data_in == 1'b0) begin
                        state <= 3'b111;
                        data_out <= 1'b0;

                    end else begin
                        state <= 3'b000;
                        data_out <= 1'b0;

                    end
                end
                3'b111: begin
                    if (data_in == 1'b1) begin
                        state <= 3'b000;
                        data_out <= 1'b0;

                    end else begin
                        state <= 3'b001;
                        data_out <= 1'b0;

                    end
                end
                default: begin
                    state <= 3'b000;
                    data_out <= 1'b0;
                    $display("dont't know.");
                end
            endcase
        end
    end
endmodule

