module traffic_light(
    input rst_n, clk, pass_request,
    output [7:0] clock, output red, yellow, green
);

parameter idle=2'b00, s1_red=2'b01, s2_yellow=2'b10, s3_green=2'b11;

reg [1:0] state;
reg p_red, p_yellow, p_green;
reg [7:0] cnt;
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= idle;
    end
    else begin

        case (state)
            idle: 
                state <= s1_red;
            s1_red: 
                if (cnt<=3) 
                    state <= s3_green;
                else 
                    state <= s1_red;
            s2_yellow: 
                if (cnt<=3) 
                    state <= s1_red;
                else 
                    state <= s2_yellow;
            s3_green:
                if (cnt<=3) 
                    state <= s2_yellow;
                else 
                    state <= s3_green;
        endcase
    end
end
always @(posedge clk or negedge rst_n) begin

    if (!rst_n) cnt <= 10;
    else begin
        if (pass_request & green) cnt <= 10;
        else if (~green & p_green) cnt <= 60;
        else if (~yellow & p_yellow) cnt <= 5;
        else if (~red & p_red) cnt <= 10;
        else begin
            if (state == s1_red) cnt <= 10;
            else if (state == s2_yellow) cnt <= 3;
            else if (state == s3_green) cnt <= 60;
        end
    end
end
always @(posedge clk or negedge rst_n) begin

    if (!rst_n) begin
        p_red <= 1'b0;
        p_yellow <= 1'b0;
        p_green <= 1'b0;
    end
    else begin
        p_red <= red;
        p_yellow <= yellow;
        p_green <= green;
    end
end
assign clock = cnt;
assign red = ~p_green & (state==s1_red);
assign yellow = ~p_green & ~p_red & (state==s2_yellow);
assign green = ~p_red & (state==s3_green);
endmodule

