module edge_detect(clk, rst_n, a, rise, down) ;
    input clk ;
    input rst_n ;
    input a ;
    output reg rise ;
    output reg down ;
    reg [1:0] state ;
    reg [1:0] next_state ;
    parameter [1:0] zero = 2'b00, rise_state = 2'b01, fall_state = 2'b10, one = 2'b11 ;
    always @ (state or a) begin
        case (state)
            zero: if (a == 1) next_state = rise_state ;
                else next_state = zero ;
            rise_state: if (a == 0) next_state = fall_state ;
                else next_state = rise_state ;
            fall_state: if (a == 1) next_state = one ;
                else next_state = zero ;
            one: if (a == 0) next_state = fall_state ;
                else next_state = one ;
        endcase
    end
    always @ (posedge clk or negedge rst_n) begin
        if (rst_n == 1'b0) begin
            state <= zero ;
            rise <= 0 ;
            down <= 0 ;
        end
        else begin
            state <= next_state ;
            case (state)
                zero: rise <= 0 ;
                rise_state: begin
                    rise <= 1 ;
                    down <= 0 ;
                end
                fall_state: begin
                    rise <= 0 ;
                    down <= 1 ;
                end
                one: begin
                    rise <= 0 ;
                    down <= 0 ;
                end
            endcase
        end
    end
endmodule

