module width_8to16(
    input clk, 
    input rst_n, 
    input valid_in, 
    input [7:0] data_in, 
    output valid_out, 
    output [15:0] data_out
) ;
    reg [7:0] data_lock;
    reg [15:0] data_reg;
    reg flag, flag_next, valid_out_reg;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            data_reg <= 0;
            flag <= 0;
        end
        else begin
            if (valid_in) begin
                if (flag) begin
                    data_reg <= {data_lock, data_in};
                    flag <= flag_next;
                end
                else begin
                    data_lock <= data_in;
                    flag <= flag_next;
                end
            end
            else begin
                flag <= flag;
            end
        end
    end
    always @(*) begin
        flag_next <= flag;
        if (valid_in && !flag) flag_next <= 1;
        if (flag && valid_in && data_reg[7:0] == data_lock[7:0]) flag_next <= 0;
    end
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) valid_out_reg <= 0;
        else begin
            if (flag && valid_in && data_reg[7:0] == data_lock[7:0]) valid_out_reg <= 1;
            else valid_out_reg <= 0;
        end
    end
    assign valid_out = valid_out_reg;
    assign data_out = data_reg;
endmodule

