module sub_64bit (
    input [63:0] A,
    input [63:0] B,
    output [63:0] result,
    output overflow
) ;
wire [63:0] res_sub;
wire ovf_pos, ovf_neg;
assign res_sub = A - B;
assign ovf_pos = (A[63] == 1'b0) && (B[63] == 1'b1) && (res_sub[63] == 1'b1);
assign ovf_neg = (A[63] == 1'b1) && (B[63] == 1'b0) && (res_sub[63] == 1'b0);
assign overflow = ovf_pos || ovf_neg;
assign result = res_sub;
endmodule

